            QQpaR1I9Q1pHUgpaR1U9TlZTUQpaSEE9WkdaSgpaSE09VkdTSApaSFA9Q1pIUApaSFk9WkxaVwpaSUE9VVVCVwpaSUM9U0NUTwpaSUc9R09HRwpaSUg9TU1aSApaSVM9SExaTgpaSVg9VUVWVgpaSVo9T1BaTQpa
            Skc9Q1pKRwpaSk49Q1pKTgpaS0I9RkxLWQpaS0U9Q1pLRQpaS1A9VUVTVQpaTE89TU1aTwpaTFI9U0NMTgpaTFg9SFNaQQpaTUg9Q1pNTApaTU09TU1aTQpaTVQ9Q1pNVApaTkQ9RFJaUgpaTkU9WU5XTgpaTlo9
            SFRaQQpaT0U9RURHTApaT1M9U0NKTwpaUEI9Q1pQQgpaUEM9U0NQQwpaUEg9S1pQSApaUE89Q1pQTwpaUU49TlpRTgpaUVc9RURSWgpaUVo9WkJaSgpaUkg9TFNaSApaUkk9V0FCTwpaUko9Q1pSSgpaUk09V0FK
            SQpaU0E9TVlTTQpaU0U9Rk1FUApaU0o9Q1pTSgpaU1M9RElTUwpaU1Q9Q1pTVApaU1c9Q1pTVwpaVEE9TlRHWQpaVEg9TEdaQQpaVE09Q1pUTQpaVFI9VUtLVgpaVFU9VUJCWQpaVUM9Q1pVQwpaVUQ9U0NBQwpa
            VUg9WkdTRApaVUw9T0VaTApaVU09Q1pVTQpaVkE9Rk1NTgpaVks9VkxTSwpaV0E9Rk1ORApaV0w9Q1pXTApaWFQ9VUJUVApaWUk9WlVaWQpaWUw9VkdTWQpaWkU9VUJCWgpaWk89VUhTTwpaWlU9RldVVQpaWlY9
            S1paVg==
            """
        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters), let text = String(data: data, encoding: .utf8) else { return [:] }
        return Dictionary(uniqueKeysWithValues: text.split(separator: "\n").compactMap { line in
            let pair = line.split(separator: "=", maxSplits: 1).map(String.init)
            return pair.count == 2 ? (pair[0], pair[1]) : nil
        })
    }()
    static func canonical(_ input: String) -> String {
        let code = input.uppercased().filter { $0.isASCII && ($0.isLetter || $0.isNumber) }
        return aliases[code] ?? code
    }
    static func codes(_ text: String) -> [String] {
        text.uppercased().components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { (3...4).contains($0.count) && $0.contains(where: { $0.isLetter }) }.map(canonical)
    }
    static func formatted(_ text: String) -> String {
        codes(text).joined(separator: " → ")
    }
}

enum AirportPreferences {
    static func read(_ input: String, defaults: UserDefaults = .standard) -> (rating: Int, comment: String) {
        let code = AirportRoute.canonical(input)
        let aliases = AirportRoute.aliases.filter { $0.value == code }.map(\.key).sorted()
        let ratingKey = "airportRating-" + code, commentKey = "airportNotes-" + code
        if defaults.object(forKey: ratingKey) == nil,
           let alias = aliases.first(where: { defaults.object(forKey: "airportRating-" + $0) != nil }) {
            defaults.set(defaults.integer(forKey: "airportRating-" + alias), forKey: ratingKey)
        }
        if defaults.object(forKey: commentKey) == nil {
            var seen = Set<String>()
            let notes = aliases.compactMap { defaults.string(forKey: "airportNotes-" + $0) }
                .filter { !$0.isEmpty && seen.insert($0).inserted }
            if !notes.isEmpty { defaults.set(notes.joined(separator: "\n\n"), forKey: commentKey) }
        }
        return (min(5, max(0, defaults.integer(forKey: ratingKey))), defaults.string(forKey: commentKey) ?? "")
    }
}

nonisolated enum AircraftNames {
    static func registration(_ value: String) -> String {
        value.uppercased().filter { $0.isLetter || $0.isNumber }
    }
    static func display(_ value: String) -> String {
        let raw = value.split(whereSeparator: { $0.isWhitespace }).joined(separator: " ")
        // Some exports put a precise model code before a comma and the marketing name after it.
        // Only normalize recognized codes; never guess a variant from the marketing name.
        if let comma = raw.firstIndex(of: ",") {
            let code = String(raw[..<comma]).trimmingCharacters(in: .whitespacesAndNewlines)
            let normalized = display(code)
            if normalized != code { return normalized }
            let compactCode = code.uppercased().filter { $0.isLetter || $0.isNumber }
            if compactCode.range(of: #"^BE[0-9]{2,3}[A-Z]?$"#, options: .regularExpression) != nil {
                return "Beechcraft " + String(compactCode.dropFirst(2))
            }
        }
        let compact = raw.uppercased().filter { $0.isLetter || $0.isNumber }
        let cessnas = ["150", "150L", "150M", "152", "172", "172N", "172P", "172R", "172S", "172RG", "177", "177RG", "182", "182P", "182Q", "182R", "182S", "182T", "T182T", "182RG", "T182RG", "206", "U206G", "T206H"]
        for code in cessnas where [code, "C" + code, "CESSNA" + code, "CESSNAAIRCRAFTCOMPANY" + code, "CESSNAAIRCRAFTCO" + code, "TEXTRONAVIATIONINC" + code].contains(compact) {
            return "Cessna " + code
        }
        var cessnaCode = compact
        for maker in ["CESSNAAIRCRAFTCOMPANY", "CESSNAAIRCRAFTCO", "CESSNA", "TEXTRONAVIATIONINC"] {
            if cessnaCode.hasPrefix(maker) { cessnaCode = String(cessnaCode.dropFirst(maker.count)); break }
        }
        if cessnaCode.hasPrefix("C") { cessnaCode = String(cessnaCode.dropFirst()) }
        let knownSeries = ["150", "152", "172", "177", "180", "182", "185", "188", "206", "207", "210", "310", "340", "402", "414", "421", "425"]
        if cessnaCode.range(of: "^[TU]?[0-9]{3}[A-Z]{0,3}$", options: .regularExpression) != nil,
           knownSeries.contains(where: { cessnaCode.hasPrefix($0) || cessnaCode.hasPrefix("T" + $0) || cessnaCode.hasPrefix("U" + $0) }) {
            return "Cessna " + cessnaCode
        }
        for (make, prefix) in [("Piper", "PA"), ("Diamond", "DA"), ("Cirrus", "SR")] {
            var model = compact
            for maker in [make.uppercased() + "AIRCRAFTINDUSTRIESINC", make.uppercased() + "AIRCRAFTINC", make.uppercased()] {
                if model.hasPrefix(maker) { model = String(model.dropFirst(maker.count)); break }
            }
            if model.hasPrefix(prefix), model.dropFirst(prefix.count).first?.isNumber == true {
                if prefix == "PA" { model = "PA-" + String(model.dropFirst(2)) }
                return make + " " + model
            }
        }
        if compact == "A36" || compact == "BEECHCRAFTA36" { return "Beechcraft A36" }
        if compact == "G36" || compact == "BEECHCRAFTG36" { return "Beechcraft G36" }
        return raw
    }
    static func hasMake(_ value: String) -> Bool {
        let display = display(value)
        return display.split(separator: " ").count >= 2 && display.contains(where: { $0.isLetter })
    }
    static func baseModel(_ value: String) -> String {
        let name = display(value)
        let patterns: [(String, String)] = [
            (#"^CESSNA\s+[TU]?([0-9]{3})[A-Z0-9 -]*$"#, "Cessna "),
            (#"^PIPER\s+PA-?([0-9]{2})[A-Z0-9 -]*$"#, "Piper PA-"),
            (#"^DIAMOND\s+DA-?([0-9]{2})[A-Z0-9 -]*$"#, "Diamond DA"),
            (#"^CIRRUS\s+SR-?([0-9]{2})[A-Z0-9 -]*$"#, "Cirrus SR"),
            (#"^CIRRUS\s+SF-?([0-9]{2})[A-Z0-9 -]*$"#, "Cirrus SF"),
            (#"^ROBINSON\s+R-?([0-9]{2})[A-Z0-9 -]*$"#, "Robinson R")
        ]
        let upper = name.uppercased()
        for (pattern, make) in patterns {
            guard let regex = try? NSRegularExpression(pattern: pattern),
                  let match = regex.firstMatch(in: upper, range: NSRange(upper.startIndex..., in: upper)),
                  let range = Range(match.range(at: 1), in: upper) else { continue }
            return make + String(upper[range])
        }
        // Keep an unfamiliar model intact rather than guessing which part names a variant.
        return name
    }
}

struct InstructorProfile: Identifiable, Codable {
    var name = ""
    var email = ""
    var certificate = ""
    var expiration: Date? = nil
    var noExpiration = false
    var recentExperienceEnd: Date? = nil
    var id: String { certificate.trimmingCharacters(in: .whitespacesAndNewlines).uppercased() }
}

struct InstructorSignature: Codable {
    var instructor: InstructorProfile
    var comments: String
    var inkPNG: Data
    var signedAt: Date
    var agreedAt: Date
    var flightDigest: String
    var flightSnapshot: Data
    var version = 1
    static let agreement = "The app cannot verify a signature or an instructor's identity, certificate, or authority. I affirm that the instructor named on this entry will personally review and sign it; the student will not sign on the instructor's behalf."
    func matches(_ flight: Flight) -> Bool { version == 1 && flightDigest == flight.recordDigest }
}

struct MilestoneConfirmation: Codable {
    var flightDigest: String
    var confirmedAt: Date
    var accepted: Bool
    var creditedValue: Double
    var statement: String
    var version = 1
    func matches(_ flight: Flight, statement: String) -> Bool {
        version == 1 && flightDigest == flight.recordDigest && self.statement == statement
    }
}

// Optional facts supplement ordinary logbook times; no separate checkride hour ledger.
struct FlightFacts: Codable {
    var flags: Set<String> = []
    var counts: [String: Int] = [:]
    var amounts: [String: Double] = [:]
    var text: [String: String] = [:]
    nonisolated func has(_ key: String) -> Bool { flags.contains(key) }
}

struct Flight: Identifiable, Codable {
    var id = UUID()
    var route = ""
    var date = ""
    var aircraft = ""
    var duration = "0.0"
    var dayLandings = 0
    var nightLandings = 0
    var pic = 0.0
    var night = 0.0
    var imc = 0.0
    var simulatedInstrument = 0.0
    var dual = 0.0
    var instructor = 0.0
    var crossCountry = 0.0
    var approaches = ""
    var approachCount = 0
    var holds = 0
    var tracking = false
    var notes = ""
    var category = "Unspecified"
    var progress: [String: Double] = [:]
    var complex = false
    var highPerformance = false
    var taa = false
    var facts = FlightFacts()
    var legacyPhotoKey: String?
    var signature: InstructorSignature?
    var confirmations: [String: MilestoneConfirmation] = [:]

    var landings: Int { dayLandings + nightLandings }
    var total: Double { number(duration) }
    var flightDate: Date? { FlightDates.parse(date) }
    var shortDate: String { flightDate.map { FlightDates.string($0, format: "M/d/yy") } ?? date }
    var registration: String { AircraftNames.registration(aircraft.components(separatedBy: "·").first ?? aircraft) }
    var aircraftModel: String {
        AircraftNames.display(aircraft.components(separatedBy: "·").dropFirst().joined(separator: "·"))
    }
    // A stable snapshot binds signatures and confirmations to the reviewed record.
    // Photos and confirmation receipts are not part of the signed flight entry.
    var recordSnapshot: Data {
        var copy = self
        copy.signature = nil; copy.confirmations = [:]; copy.legacyPhotoKey = nil
        copy.aircraft = registration + " · " + aircraftModel
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        // Sets do not have deterministic encoding order. Store their sorted form in a separate envelope.
        let flags = copy.facts.flags.sorted(); copy.facts.flags = []
        let payload = (try? encoder.encode(copy)) ?? Data()
        struct Envelope: Encodable { var schema: Int; var record: Data; var flags: [String] }
        return (try? encoder.encode(Envelope(schema: 1, record: payload, flags: flags))) ?? Data()
    }
    var recordDigest: String { SHA256.hash(data: recordSnapshot).map { String(format: "%02x", $0) }.joined() }
    var validSignature: InstructorSignature? { signature.flatMap { $0.matches(self) ? $0 : nil } }
    var airports: [String] { AirportRoute.codes(route) }
    var photoKey: String { id.uuidString }

    enum CodingKeys: String, CodingKey {
        case id, route, date, aircraft, duration, landings, dayLandings, nightLandings
        case pic, night, imc, simulatedInstrument, dual, instructor, crossCountry
        case approaches, approachCount, holds, tracking, notes, category
        case complex, highPerformance, taa, legacyPhotoKey, progress, facts, signature, confirmations
    }
    init() {}
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decodeIfPresent(UUID.self, forKey: .id) ?? UUID()
        route = try c.decode(String.self, forKey: .route)
        date = try c.decode(String.self, forKey: .date)
        aircraft = try c.decode(String.self, forKey: .aircraft)
        duration = try c.decode(String.self, forKey: .duration)
        nightLandings = try c.decodeIfPresent(Int.self, forKey: .nightLandings) ?? 0
        dayLandings = try c.decodeIfPresent(Int.self, forKey: .dayLandings)
            ?? max(0, (try c.decodeIfPresent(Int.self, forKey: .landings) ?? 0) - nightLandings)
        pic = try c.decodeIfPresent(Double.self, forKey: .pic) ?? 0
        night = try c.decodeIfPresent(Double.self, forKey: .night) ?? 0
        imc = try c.decodeIfPresent(Double.self, forKey: .imc) ?? 0
        simulatedInstrument = try c.decodeIfPresent(Double.self, forKey: .simulatedInstrument) ?? 0
        dual = try c.decodeIfPresent(Double.self, forKey: .dual) ?? 0
        instructor = try c.decodeIfPresent(Double.self, forKey: .instructor) ?? 0
        crossCountry = try c.decodeIfPresent(Double.self, forKey: .crossCountry) ?? 0
        approaches = try c.decodeIfPresent(String.self, forKey: .approaches) ?? ""
        approachCount = try c.decodeIfPresent(Int.self, forKey: .approachCount) ?? 0
        holds = try c.decodeIfPresent(Int.self, forKey: .holds) ?? 0
        tracking = try c.decodeIfPresent(Bool.self, forKey: .tracking) ?? false
        notes = try c.decodeIfPresent(String.self, forKey: .notes) ?? ""
        category = try c.decodeIfPresent(String.self, forKey: .category) ?? "ASEL"
        progress = try c.decodeIfPresent([String: Double].self, forKey: .progress) ?? [:]
        complex = try c.decodeIfPresent(Bool.self, forKey: .complex) ?? false
        highPerformance = try c.decodeIfPresent(Bool.self, forKey: .highPerformance) ?? false
        taa = try c.decodeIfPresent(Bool.self, forKey: .taa) ?? false
        facts = try c.decodeIfPresent(FlightFacts.self, forKey: .facts) ?? FlightFacts()
        signature = try c.decodeIfPresent(InstructorSignature.self, forKey: .signature)
        confirmations = try c.decodeIfPresent([String: MilestoneConfirmation].self, forKey: .confirmations) ?? [:]
        legacyPhotoKey = try c.decodeIfPresent(String.self, forKey: .legacyPhotoKey)
            ?? "\(route)-\(date)-\(aircraft)"
    }
    func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(id, forKey: .id)
        try c.encode(route, forKey: .route)
        try c.encode(date, forKey: .date)
        try c.encode(aircraft, forKey: .aircraft)
        try c.encode(duration, forKey: .duration)
        try c.encode(landings, forKey: .landings)
        try c.encode(dayLandings, forKey: .dayLandings)
        try c.encode(nightLandings, forKey: .nightLandings)
        try c.encode(pic, forKey: .pic)
        try c.encode(night, forKey: .night)
        try c.encode(imc, forKey: .imc)
        try c.encode(simulatedInstrument, forKey: .simulatedInstrument)
        try c.encode(dual, forKey: .dual)
        try c.encode(instructor, forKey: .instructor)
        try c.encode(crossCountry, forKey: .crossCountry)
        try c.encode(approaches, forKey: .approaches)
        try c.encode(approachCount, forKey: .approachCount)
        try c.encode(holds, forKey: .holds)
        try c.encode(tracking, forKey: .tracking)
        try c.encode(notes, forKey: .notes)
        try c.encode(category, forKey: .category)
        try c.encode(progress, forKey: .progress)
        try c.encode(complex, forKey: .complex)
        try c.encode(highPerformance, forKey: .highPerformance)
        try c.encode(taa, forKey: .taa)
        try c.encode(facts, forKey: .facts)
        try c.encodeIfPresent(legacyPhotoKey, forKey: .legacyPhotoKey)
        try c.encodeIfPresent(signature, forKey: .signature)
        try c.encode(confirmations, forKey: .confirmations)
    }
}

struct SavedAircraft: Identifiable, Codable {
    var registration: String
    var model: String
    var category: String? = nil
    var complex: Bool? = nil
    var highPerformance: Bool? = nil
    var taa: Bool? = nil
    var turbine: Bool? = nil
    // Optional fields preserve aircraft saved by earlier builds.
    var detectedFeatures: [String: Bool]? = nil
    var featureCorrections: [String: Bool]? = nil
    var equipmentInfo: AircraftInfo? = nil
    var id: String { registration }
}

struct ScheduledFlight: Identifiable, Codable {
    var id = UUID()
    var date = Date()
    var title = ""
    var registration = ""
    var route = ""
    var estimatedTime = 0.0
    // Optional fields keep calendars saved by earlier builds readable.
    var endDate: Date? = nil
    var pilotName: String? = nil
    var instructorName: String? = nil
    var notes: String? = nil
    var resource: String? = nil
    var sourceScheduleID: String? = nil
    var activityType: String? = nil
    var importReviewStatus: String? = nil
    var importUnreviewedFields: [String]? = nil
    var importWarnings: [String]? = nil
    var isGround: Bool {
        activityType == "ground" || resource?.uppercased() == "GROUND"
    }
}

@MainActor final class FlightStore: ObservableObject {
    @Published private(set) var flights: [Flight] = [] {
        didSet { sortedCache = nil; statsInputCache = nil; flightIndexCache = nil; flightRevision &+= 1 }
    }
    @Published private(set) var flightRevision = 0
    let stats = StatsModel()
    private var sortedCache: [Flight]?
    private var statsInputCache: [StatsInput]?
    private var flightIndexCache: [UUID: Flight]?
    @Published private(set) var aircraft: [SavedAircraft] = []
    @Published private(set) var schedules: [ScheduledFlight] = []
    @Published private(set) var instructors: [InstructorProfile] = []
    @Published private(set) var medical: FAAMedical?
    @Published var errorMessage: String?
    @Published var photoRevision = 0
    @Published private(set) var canUndoFlightReset = UserDefaults.standard.data(forKey: "savedFlights_beforeTestingReset") != nil
    private var loadFailed = false
    init() {
        if let data = UserDefaults.standard.data(forKey: "savedFlights") {
            do { flights = try JSONDecoder().decode([Flight].self, from: data) }
            catch {
                loadFailed = true
                errorMessage = "The saved logbook could not be read. It has not been overwritten."
            }
        }
        aircraft = Self.read("logbookAircraft", as: [SavedAircraft].self) ?? []
        schedules = Self.read("logbookSchedules", as: [ScheduledFlight].self) ?? []
        instructors = Self.read("logbookInstructors", as: [InstructorProfile].self) ?? []
        medical = Self.read("logbookMedical", as: FAAMedical.self)
        if !loadFailed {
            var updated = flights
            if AircraftFeatureSync.applySavedFeatures(aircraft, to: &updated) {
                do {
                    let data = try JSONEncoder().encode(updated)
                    backup()
                    UserDefaults.standard.set(data, forKey: "savedFlights")
                    flights = updated
                } catch { errorMessage = error.localizedDescription }
            }
        }
    }
    private static func read<T: Decodable>(_ key: String, as type: T.Type) -> T? {
        guard let data = UserDefaults.standard.data(forKey: key) else { return nil }
        return try? JSONDecoder().decode(type, from: data)
    }
    var sorted: [Flight] {
        if let sortedCache { return sortedCache }
        typealias SortEntry = (offset: Int, flight: Flight, date: Date)
        var entries: [SortEntry] = []
        entries.reserveCapacity(flights.count)
        for (offset, flight) in flights.enumerated() {
            let date: Date = flight.flightDate ?? Date.distantPast
            entries.append((offset: offset, flight: flight, date: date))
        }
        entries.sort { first, second in
            if first.date == second.date { return first.offset > second.offset }
            return first.date > second.date
        }
        var result: [Flight] = []
        result.reserveCapacity(entries.count)
        for entry in entries { result.append(entry.flight) }
        sortedCache = result
        return result
    }
    var statsInput: [StatsInput] {
        if let statsInputCache { return statsInputCache }
        var identities: [String: (registration: String, model: String)] = [:]
        let input = flights.enumerated().filter { !$0.element.isDevice }.map { entry in
            let f = entry.element
            let identity = identities[f.aircraft] ?? (registration: f.registration, model: f.aircraftModel)
            identities[f.aircraft] = identity
            return StatsInput(id: f.id, order: entry.offset, date: f.date, route: f.route,
                registration: identity.registration, model: identity.model, total: f.total,
                photoKey: f.photoKey, legacyPhotoKey: f.legacyPhotoKey ?? "\(f.route)-\(f.date)-\(f.aircraft)")
        }
        statsInputCache = input
        return input
    }
    func flight(_ id: UUID) -> Flight? {
        if flightIndexCache == nil { flightIndexCache = Dictionary(flights.map { ($0.id, $0) }, uniquingKeysWith: { _, latest in latest }) }
        return flightIndexCache?[id]
    }
    var fleet: [SavedAircraft] {
        var result = Dictionary(aircraft.map { item -> (String, SavedAircraft) in
            var normalized = item
            normalized.registration = AircraftNames.registration(item.registration)
            normalized.model = AircraftNames.display(item.model)
            return (normalized.registration, normalized)
        }, uniquingKeysWith: { _, new in new })
        for f in sorted.reversed() where !f.isDevice {
            if !aircraft.contains(where: { AircraftNames.registration($0.registration) == f.registration }) {
                result[f.registration] = SavedAircraft(registration: f.registration, model: f.aircraftModel, category: f.category,
                    complex: f.complex ? true : nil, highPerformance: f.highPerformance ? true : nil,
                    taa: f.taa ? true : nil, turbine: f.facts.has("turbine") ? true : nil,
                    detectedFeatures: Dictionary(uniqueKeysWithValues: AircraftFeature.allCases.filter { f.hasAircraftFeature($0) }.map { ($0.rawValue, true) }))
            }
        }
        return result.values.filter { !["FFS", "FTD", "ATD"].contains($0.category ?? "") }.sorted { a, b in
            let ah = flights.filter { $0.registration == a.registration }.reduce(0) { $0 + $1.total }
            let bh = flights.filter { $0.registration == b.registration }.reduce(0) { $0 + $1.total }
            return ah == bh ? a.registration < b.registration : ah > bh
        }
    }
    @discardableResult func save(_ flight: Flight, photos: [UIImage], aircraft input: SavedAircraft? = nil,
                                featureChanges: [String: Bool] = [:]) -> Bool {
        guard !loadFailed else { errorMessage = "Restore the unreadable logbook before saving."; return false }
        let issues = FlightEntryValidation.savingIssues(flight)
        guard issues.isEmpty else { errorMessage = issues.map(\.message).joined(separator: "\n"); return false }
        var updated = flights
        if let index = updated.firstIndex(where: { $0.id == flight.id }) { updated[index] = flight }
        else { updated.append(flight) }
        var updatedAircraft = aircraft
        if var item = input {
            item.registration = AircraftNames.registration(item.registration)
            item.model = AircraftNames.display(item.model)
            updatedAircraft.removeAll { AircraftNames.registration($0.registration) == item.registration }
            updatedAircraft.append(item)
            let features = item.resolvedEquipmentFeatures.merging(featureChanges, uniquingKeysWith: { _, edit in edit })
            AircraftFeatureSync.apply(features, registration: item.registration, to: &updated)
        }
        do {
            let encoded = try JSONEncoder().encode(updated)
            let encodedAircraft = input == nil ? nil : try JSONEncoder().encode(updatedAircraft)
            try PhotoStore.save(photos, key: flight.photoKey)
            backup()
            UserDefaults.standard.set(encoded, forKey: "savedFlights")
            if let encodedAircraft { UserDefaults.standard.set(encodedAircraft, forKey: "logbookAircraft") }
            flights = updated
            if input != nil { aircraft = updatedAircraft }
            photoRevision += 1
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    // CSV automatic saves commit once, so a failed batch never leaves a partially imported logbook.
    @discardableResult func saveImportedFlights(_ imported: [Flight], aircraft incomingAircraft: [SavedAircraft] = []) -> Bool {
        guard !loadFailed else { errorMessage = "Restore the unreadable logbook before saving."; return false }
        guard imported.allSatisfy({ CSVImportReview.validationIssues($0).isEmpty }) else {
            errorMessage = "Some imported flights need required details before they can be saved."; return false
        }
        guard !imported.isEmpty else { return true }
        var ids = Set(flights.map(\.id))
        let additions = imported.filter { ids.insert($0.id).inserted }
        guard !additions.isEmpty else { return true }
        var updatedAircraft = aircraft
        for item in incomingAircraft where additions.contains(where: { $0.registration == AircraftNames.registration(item.registration) }) {
            updatedAircraft.removeAll { AircraftNames.registration($0.registration) == AircraftNames.registration(item.registration) }
            updatedAircraft.append(item)
        }
        do {
            var updated = flights + additions
            AircraftFeatureSync.applySavedFeatures(updatedAircraft, to: &updated)
            let encoded = try JSONEncoder().encode(updated)
            let encodedAircraft = incomingAircraft.isEmpty ? nil : try JSONEncoder().encode(updatedAircraft)
            backup()
            UserDefaults.standard.set(encoded, forKey: "savedFlights")
            if let encodedAircraft { UserDefaults.standard.set(encodedAircraft, forKey: "logbookAircraft") }
            flights = updated
            if !incomingAircraft.isEmpty { aircraft = updatedAircraft }
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    func delete(_ flight: Flight) {
        guard !loadFailed else { return }
        let updated = flights.filter { $0.id != flight.id }
        do {
            let encoded = try JSONEncoder().encode(updated)
            backup()
            UserDefaults.standard.set(encoded, forKey: "savedFlights")
            flights = updated
            // Keep photo files recoverable; removing a flight does not erase them.
        } catch { errorMessage = error.localizedDescription }
    }
    private func backup() {
        let defaults = UserDefaults.standard
        if defaults.data(forKey: "savedFlights_beforePrototypeUI") == nil,
           let original = defaults.data(forKey: "savedFlights") {
            defaults.set(original, forKey: "savedFlights_beforePrototypeUI")
        }
    }
    @discardableResult func deleteAllFlightsForTesting() -> Bool {
        guard PrototypeTesting.enablesFlightReset, !loadFailed, !flights.isEmpty else { return false }
        do {
            let defaults = UserDefaults.standard
            var previouslyDeleted: [Flight] = []
            if let data = defaults.data(forKey: "savedFlights_beforeTestingReset") {
                // Preserve earlier resets too; an unreadable backup aborts without clearing anything.
                previouslyDeleted = try JSONDecoder().decode([Flight].self, from: data)
            }
            var ids = Set(flights.map(\.id))
            let recoverable = flights + previouslyDeleted.filter { ids.insert($0.id).inserted }
            let snapshot = try JSONEncoder().encode(recoverable)
            let empty = try JSONEncoder().encode([Flight]())
            backup()
            defaults.set(snapshot, forKey: "savedFlights_beforeTestingReset")
            defaults.set(empty, forKey: "savedFlights")
            flights = []; canUndoFlightReset = true
            // Aircraft, schedules, instructor records and all photo files are retained.
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    @discardableResult func undoFlightResetForTesting() -> Bool {
        guard PrototypeTesting.enablesFlightReset, !loadFailed,
              let data = UserDefaults.standard.data(forKey: "savedFlights_beforeTestingReset") else { return false }
        do {
            let saved = try JSONDecoder().decode([Flight].self, from: data)
            var ids = Set(flights.map(\.id))
            var restored = flights + saved.filter { ids.insert($0.id).inserted }
            AircraftFeatureSync.applySavedFeatures(aircraft, to: &restored)
            let encoded = try JSONEncoder().encode(restored)
            UserDefaults.standard.set(encoded, forKey: "savedFlights"); flights = restored
            UserDefaults.standard.removeObject(forKey: "savedFlights_beforeTestingReset")
            canUndoFlightReset = false
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    @discardableResult func addAircraft(_ input: SavedAircraft, featureChanges: [String: Bool] = [:]) -> Bool {
        guard !loadFailed else { errorMessage = "Restore the unreadable logbook before changing aircraft equipment."; return false }
        var item = input
        item.registration = AircraftNames.registration(input.registration); item.model = AircraftNames.display(input.model)
        var list = aircraft.filter { AircraftNames.registration($0.registration) != item.registration }
        list.append(item)
        var updated = flights
        let features = item.resolvedEquipmentFeatures.merging(featureChanges, uniquingKeysWith: { _, edit in edit })
        let changed = AircraftFeatureSync.apply(features, registration: item.registration, to: &updated)
        do {
            let data = try JSONEncoder().encode(list)
            let flightData = changed ? try JSONEncoder().encode(updated) : nil
            if let flightData {
                backup()
                UserDefaults.standard.set(flightData, forKey: "savedFlights")
            }
            UserDefaults.standard.set(data, forKey: "logbookAircraft")
            aircraft = list
            if changed { flights = updated }
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    @discardableResult func confirm(_ flightID: UUID, key: String, statement: String, value: Double, accepted: Bool) -> Bool {
        guard !loadFailed, value.isFinite, value >= 0,
              let index = flights.firstIndex(where: { $0.id == flightID }) else { return false }
        var updated = flights
        updated[index].confirmations[key] = MilestoneConfirmation(flightDigest: updated[index].recordDigest,
            confirmedAt: Date(), accepted: accepted, creditedValue: value, statement: statement)
        do {
            let data = try JSONEncoder().encode(updated); backup()
            UserDefaults.standard.set(data, forKey: "savedFlights"); flights = updated
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    func clearConfirmation(_ flightID: UUID, key: String) {
        guard !loadFailed, let index = flights.firstIndex(where: { $0.id == flightID }) else { return }
        var updated = flights; updated[index].confirmations.removeValue(forKey: key)
        do {
            let data = try JSONEncoder().encode(updated); backup()
            UserDefaults.standard.set(data, forKey: "savedFlights"); flights = updated
        } catch { errorMessage = error.localizedDescription }
    }
    @discardableResult func rememberInstructor(_ instructor: InstructorProfile) -> Bool {
        var list = instructors.filter { $0.id != instructor.id }; list.append(instructor)
        do {
            let data = try JSONEncoder().encode(list)
            UserDefaults.standard.set(data, forKey: "logbookInstructors"); instructors = list
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    @discardableResult func saveMedical(_ value: FAAMedical) -> Bool {
        do {
            let data = try JSONEncoder().encode(value)
            UserDefaults.standard.set(data, forKey: "logbookMedical"); medical = value
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    func removeMedical() { UserDefaults.standard.removeObject(forKey: "logbookMedical"); medical = nil }
    @discardableResult func saveSchedule(_ item: ScheduledFlight) -> Bool {
        let issues = ScheduleImportReview.validationIssues(item)
        guard issues.isEmpty else { errorMessage = issues.map(\.message).joined(separator: "\n"); return false }
        var list = schedules.filter { $0.id != item.id }
        list.append(item)
        do {
            let data = try JSONEncoder().encode(list)
            UserDefaults.standard.set(data, forKey: "logbookSchedules"); schedules = list
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    @discardableResult func saveImportedSchedules(_ imported: [ScheduledFlight]) -> Bool {
        guard imported.allSatisfy({ ScheduleImportReview.validationIssues($0).isEmpty }) else {
            errorMessage = "Some scheduled flights need a valid date or time before saving."; return false
        }
        var ids = Set(schedules.map(\.id))
        var sources = Set(schedules.compactMap { $0.sourceScheduleID?.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty })
        let additions = imported.filter { item in
            guard ids.insert(item.id).inserted else { return false }
            let source = item.sourceScheduleID?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            return source.isEmpty || sources.insert(source).inserted
        }
        guard !additions.isEmpty else { return true }
        do {
            let updated = schedules + additions
            let data = try JSONEncoder().encode(updated)
            UserDefaults.standard.set(data, forKey: "logbookSchedules"); schedules = updated
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    func deleteSchedule(_ item: ScheduledFlight) {
        let list = schedules.filter { $0.id != item.id }
        if let data = try? JSONEncoder().encode(list) {
            UserDefaults.standard.set(data, forKey: "logbookSchedules"); schedules = list
            Task { await ReminderManager.rebuild(list) }
        }
    }
}

enum PhotoStore {
    static let folder: URL = {
        let url = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("FlightPhotos", isDirectory: true)
        try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }()
    static func safe(_ key: String) -> String {
        key.map { $0.isLetter || $0.isNumber ? String($0) : "_" }.joined()
    }
    static func load(key: String) -> [UIImage] {
        let url = folder.appendingPathComponent(safe(key) + ".plist")
        guard let data = try? Data(contentsOf: url),
              let images = try? PropertyListDecoder().decode([Data].self, from: data) else { return [] }
        return images.compactMap { UIImage(data: $0) }
    }
    static func load(_ flight: Flight) -> [UIImage] {
        let stableURL = folder.appendingPathComponent(safe(flight.photoKey) + ".plist")
        if FileManager.default.fileExists(atPath: stableURL.path) { return load(key: flight.photoKey) }
        return load(key: flight.legacyPhotoKey ?? "\(flight.route)-\(flight.date)-\(flight.aircraft)")
    }
    static func save(_ images: [UIImage], key: String) throws {
        let data = try PropertyListEncoder().encode(images.compactMap { $0.jpegData(compressionQuality: 0.82) })
        try data.write(to: folder.appendingPathComponent(safe(key) + ".plist"), options: .atomic)
    }
}

@MainActor final class AppTheme: ObservableObject {
    @Published var dark = (UserDefaults.standard.object(forKey: "isDarkMode") as? Bool) ?? true
    private var changing = false
    var background: Color { Color(hex: dark ? 0x080B0E : 0xEEF1F3) }
    var surface: Color { Color(hex: dark ? 0x12181D : 0xFFFFFF) }
    var raised: Color { Color(hex: dark ? 0x182127 : 0xF4F6F7) }
    var line: Color { Color(hex: dark ? 0x283138 : 0xDDE3E7) }
    var text: Color { Color(hex: dark ? 0xF5F7F8 : 0x0E1B2C) }
    var muted: Color { Color(hex: dark ? 0x8D969D : 0x66727E) }
    var accent: Color { Color(hex: dark ? 0xFFC548 : 0xEF9B00) }
    var cyan: Color { Color(hex: dark ? 0x19D7EE : 0x08A7C0) }
    func toggle() {
        guard !changing else { return }
        let window = UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }
            .first(where: { $0.activationState == .foregroundActive })?.windows.first(where: \.isKeyWindow)
        let snapshot = window?.snapshotView(afterScreenUpdates: false)
        if let window, let snapshot {
            snapshot.frame = window.bounds
            snapshot.isUserInteractionEnabled = false
            snapshot.accessibilityElementsHidden = true
            window.addSubview(snapshot)
            changing = true
        }
        dark.toggle()
        UserDefaults.standard.set(dark, forKey: "isDarkMode")
        guard let snapshot else { return }
        UIView.animate(withDuration: 0.85, delay: 0.08, options: [.curveEaseInOut]) {
            snapshot.alpha = 0
        } completion: { _ in
            snapshot.removeFromSuperview(); self.changing = false
        }
    }
}

extension Color {
    init(hex: UInt32) {
        self.init(.sRGB, red: Double((hex >> 16) & 255) / 255,
                  green: Double((hex >> 8) & 255) / 255, blue: Double(hex & 255) / 255, opacity: 1)
    }
}

enum CardTone { case neutral, blue, green, airport }

struct CardStyle: ViewModifier {
    @EnvironmentObject var theme: AppTheme
    var padding: CGFloat = 18
    var tone: CardTone = .neutral
    private var colors: [Color] {
        switch tone {
        case .neutral: return theme.dark ? [Color(hex: 0x17252C), Color(hex: 0x121A1F), Color(hex: 0x0E151A)] : [.white, Color(hex: 0xF1F5F6)]
        case .blue: return theme.dark ? [Color(hex: 0x243D49), Color(hex: 0x14222A), Color(hex: 0x0E171C)] : [Color(hex: 0xFAFDFF), Color(hex: 0xE5F1F4)]
        case .green: return theme.dark ? [Color(hex: 0x2A342F), Color(hex: 0x17211F), Color(hex: 0x111817)] : [Color(hex: 0xFBFDF8), Color(hex: 0xEDF3E9)]
        case .airport: return theme.dark ? [Color(hex: 0x172932), Color(hex: 0x10171C)] : [.white, Color(hex: 0xEEF5F7)]
        }
    }
    func body(content: Content) -> some View {
        content.padding(padding).frame(maxWidth: .infinity, alignment: .leading)
            .background(LinearGradient(colors: colors, startPoint: .topLeading, endPoint: .bottomTrailing))
            .clipShape(RoundedRectangle(cornerRadius: 22))
            .overlay(RoundedRectangle(cornerRadius: 22).stroke(LinearGradient(colors: [Color.white.opacity(theme.dark ? 0.075 : 0.9), theme.line.opacity(0.1)], startPoint: .top, endPoint: .bottom), lineWidth: 1))
            .shadow(color: (theme.dark ? Color.black : Color(hex: 0x273F4B)).opacity(theme.dark ? 0.16 : 0.11), radius: 12, x: 0, y: 8)
    }
}

extension View {
    func logbookCard(_ padding: CGFloat = 18, tone: CardTone = .neutral) -> some View { modifier(CardStyle(padding: padding, tone: tone)) }
