enum AircraftFeature: String, CaseIterable, Identifiable, Codable {
    case complex, highPerformance = "hp", taa, turbine, tailwheel
    case fixedGear, retractableGear, tricycleGear, skids, skis, floats, amphibious, flyingBoat
    case fixedPitchPropeller, controllablePitchPropeller, constantSpeedPropeller, flaps
    case manualControllablePitchPropeller
    case piston, turboprop, turboshaft, turbojet, turbofan, electric, rotaryEngine
    case pressurized, highAltitude, largeAircraft, typeRatingRequired, twoPilotCrew, simplifiedControls, robinsonSFAR73
    case glassCockpit, pfd, mfd, gps, twoAxisAutopilot
    case standardAirworthiness, experimental, restricted, specialLightSport, utilityCategory, aerobaticCategory
    var id: String { rawValue }
    var title: String {
        switch self {
        case .complex: return "Complex"
        case .highPerformance: return "High performance"
        case .taa: return "Technically advanced airplane"
        case .turbine: return "Turbine powered"
        case .tailwheel: return "Tailwheel"
        case .fixedGear: return "Fixed landing gear"
        case .retractableGear: return "Retractable landing gear"
        case .tricycleGear: return "Tricycle landing gear"
        case .skids: return "Skid landing gear"
        case .skis: return "Skis"
        case .floats: return "Floats"
        case .amphibious: return "Amphibious configuration"
        case .flyingBoat: return "Flying-boat hull"
        case .fixedPitchPropeller: return "Fixed-pitch propeller"
        case .controllablePitchPropeller: return "Controllable-pitch propeller"
        case .manualControllablePitchPropeller: return "Manual controllable-pitch propeller"
        case .constantSpeedPropeller: return "Constant-speed propeller"
        case .flaps: return "Flaps"
        case .piston: return "Piston engine"
        case .turboprop: return "Turboprop"
        case .turboshaft: return "Turboshaft"
        case .turbojet: return "Turbojet"
        case .turbofan: return "Turbofan"
        case .electric: return "Electric propulsion"
        case .rotaryEngine: return "Rotary engine"
        case .pressurized: return "Pressurized cabin"
        case .highAltitude: return "High-altitude pressurized airplane"
        case .largeAircraft: return "Large aircraft (over 12,500 lb)"
        case .typeRatingRequired: return "Type rating required"
        case .twoPilotCrew: return "Two-pilot minimum crew"
        case .simplifiedControls: return "Designated simplified flight controls"
        case .robinsonSFAR73: return "Robinson R22 / R44 (SFAR 73)"
        case .glassCockpit: return "Glass cockpit"
        case .pfd: return "Electronic primary flight display"
        case .mfd: return "Moving-map multifunction display"
        case .gps: return "GPS navigation"
        case .twoAxisAutopilot: return "Integrated two-axis autopilot"
        case .standardAirworthiness: return "Standard airworthiness certificate"
        case .experimental: return "Experimental certificate"
        case .restricted: return "Restricted certificate"
        case .specialLightSport: return "Special light-sport certificate"
        case .utilityCategory: return "Utility certification category"
        case .aerobaticCategory: return "Aerobatic certification category"
        }
    }
    var group: String {
        switch self {
        case .complex, .highPerformance, .taa, .turbine, .tailwheel: return "Training and experience"
        case .fixedGear, .retractableGear, .tricycleGear, .skids, .skis, .floats, .amphibious, .flyingBoat: return "Landing gear and configuration"
        case .fixedPitchPropeller, .controllablePitchPropeller, .constantSpeedPropeller, .flaps,
             .piston, .turboprop, .turboshaft, .turbojet, .turbofan, .electric, .rotaryEngine: return "Powerplant and controls"
        case .glassCockpit, .pfd, .mfd, .gps, .twoAxisAutopilot: return "Avionics"
        case .standardAirworthiness, .experimental, .restricted, .specialLightSport, .utilityCategory, .aerobaticCategory: return "Certification"
        default: return "Operating characteristics"
        }
    }
    // Public classifications drive forms, filters and totals. Retain the other cases
    // for detection and compatibility with previously saved equipment and signatures.
    static let pilotFeatures: [AircraftFeature] = [
        .complex, .highPerformance, .taa, .turbine, .tailwheel
    ]
    static let pilotGroups = ["Training and experience"]
    var pilotGroup: String { "Training and experience" }
    // Parent/child features can coexist. Mutually exclusive configurations cannot.
    var alternatives: [AircraftFeature] {
        switch self {
        case .fixedGear: return [.retractableGear]
        case .retractableGear: return [.fixedGear]
        case .tailwheel: return [.tricycleGear, .skids]
        case .tricycleGear: return [.tailwheel, .skids]
        case .skids: return [.tailwheel, .tricycleGear]
        case .fixedPitchPropeller: return [.controllablePitchPropeller, .constantSpeedPropeller, .manualControllablePitchPropeller]
        case .controllablePitchPropeller, .constantSpeedPropeller, .manualControllablePitchPropeller: return [.fixedPitchPropeller]
        case .piston, .turboprop, .turboshaft, .turbojet, .turbofan, .electric, .rotaryEngine:
            return [.piston, .turboprop, .turboshaft, .turbojet, .turbofan, .electric, .rotaryEngine].filter { $0 != self }
        case .standardAirworthiness, .experimental, .restricted, .specialLightSport:
            return [.standardAirworthiness, .experimental, .restricted, .specialLightSport].filter { $0 != self }
        default: return []
        }
    }
}

enum AircraftFeatures {
    struct Detection {
        var values: [String: Bool] = [:]
        var horsepower: Double? = nil
        var engines: Int? = nil
        var source = ""
        var modelSourceURL: URL? = nil
    }
    nonisolated static func parts(_ model: String, info: AircraftInfo?) -> (String, String) {
        if let info, AircraftNames.display(info.model) == AircraftNames.display(model),
           let make = info.registryMake, let code = info.registryModel { return (make, code) }
        let text = AircraftNames.display(model).uppercased()
        let makers = ["AMERICAN CHAMPION", "ROBINSON HELICOPTER", "DIAMOND AIRCRAFT", "CIRRUS DESIGN", "TEXTRON AVIATION", "BEECHCRAFT", "BEECH", "CHAMPION", "CESSNA", "PIPER", "DIAMOND", "CIRRUS", "ROBINSON"]
        for maker in makers where text.hasPrefix(maker + " ") {
            return (maker, String(text.dropFirst(maker.count)).trimmingCharacters(in: .whitespaces))
        }
        let words = text.split(separator: " ")
        return (words.dropLast().joined(separator: " "), String(words.last ?? ""))
    }
    static func detect(_ model: String, category: String, info: AircraftInfo? = nil) -> Detection {
        let (make, rawCode) = parts(model, info: info)
        let code = AircraftReference.key(rawCode)
        let maker = AircraftReference.key(make)
        let matchingInfo = info.flatMap { AircraftNames.display($0.model) == AircraftNames.display(model) ? $0 : nil }
        let reference = AircraftReference.model(make: make, code: rawCode)
        let engine = matchingInfo.flatMap { AircraftReference.engine(make: $0.engineMake ?? "", code: $0.engineModel ?? "") }
        var result = Detection(engines: reference?.engines)
        var sources: [String] = []
        func set(_ feature: AircraftFeature, _ value: Bool = true) { result.values[feature.rawValue] = value }
        func stock(_ features: [AircraftFeature], horsepower: Double? = nil) {
            features.forEach { set($0) }; if let horsepower { result.horsepower = horsepower }
            if !sources.contains("Stock model equipment") { sources.append("Stock model equipment") }
        }
        let airplane = ["ASEL", "ASES", "AMEL", "AMES"].contains(category)
            || ["4", "5"].contains(reference?.type ?? "")
        let sea = ["ASES", "AMES"].contains(category)
        let isCessna = maker.contains("CESSNA") || maker.contains("TEXTRON")
        let isPiper = maker.contains("PIPER")
        let isDiamond = maker.contains("DIAMOND")
        let isCirrus = maker.contains("CIRRUS")
        let isChampion = maker.contains("CHAMPION") || maker.contains("BELLANCA")
        if isCessna {
            if code.range(of: "^(150[A-M]?|A150[KL M]?|152|A152|172[A-S]?|R172[EK]|177[A-B]?)$".replacingOccurrences(of: " ", with: ""), options: .regularExpression) != nil {
                stock([.fixedGear, .tricycleGear, .fixedPitchPropeller, .flaps, .piston]); set(.complex, false)
                if ["172N", "172P", "172R"].contains(code) { result.horsepower = 160 }
                if code == "172S" { result.horsepower = 180 }
            }
            if ["172RG", "177RG", "R182", "TR182", "182RG", "T182RG"].contains(code) {
                stock([.retractableGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston])
                if code == "172RG" { result.horsepower = 180 }
            }
            if code.range(of: "^T?182[A-T]?$", options: .regularExpression) != nil {
                stock([.fixedGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston, .highPerformance]); set(.complex, false)
                if code == "182T" { result.horsepower = 230 }; if code == "T182T" { result.horsepower = 235 }
            }
            if ["180", "180A", "180B", "180C", "180D", "180E", "180F", "180G", "180H", "180J", "180K", "185", "185A", "185B", "185C", "185D", "185E", "A185E", "A185F"].contains(code) {
                stock([.fixedGear, .tailwheel, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston, .highPerformance])
            }
            if ["208", "208A", "208B"].contains(code) {
                stock([.fixedGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .turboprop, .highPerformance])
            }
        }
        if isPiper {
            if ["PA28140", "PA28150", "PA28151", "PA28160", "PA28161", "PA28180", "PA28181"].contains(code) {
                stock([.fixedGear, .tricycleGear, .fixedPitchPropeller, .flaps, .piston]); set(.complex, false)
            }
            if ["PA28R180", "PA28R200", "PA28R201", "PA28RT201", "PA28R201T", "PA28RT201T", "PA44180", "PA44180T"].contains(code) {
                stock([.retractableGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston])
                if ["PA28R200", "PA28R201", "PA28RT201", "PA28R201T", "PA28RT201T"].contains(code) { result.horsepower = 200 }
                if code == "PA44180" { result.horsepower = 180 }
            }
            if ["PA46", "PA46350P", "PA46310P", "PA46500TP", "PA46600TP", "PA46700TP"].contains(code), code != "PA46" {
                stock([.retractableGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .pressurized])
                // The M350's 25,000-ft limit does NOT satisfy the >25,000-ft endorsement threshold.
                if ["PA46500TP", "PA46600TP", "PA46700TP"].contains(code) { stock([.highAltitude, .turboprop]) }
            }
        }
        // Beechcraft Duchess 76 POH: retractable gear, flaps and constant-speed props;
        // two 180-hp engines. Power is evaluated per engine, not as 360 hp combined.
        if maker.contains("BEECH"), ["76", "BE76", "76DUCHESS", "DUCHESS76"].contains(code) {
            stock([.retractableGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston], horsepower: 180)
        }
        if maker.contains("BEECH"), ["A36", "A36TC", "B36TC", "G36", "B58", "G58", "58", "58P", "58TC"].contains(code) {
            stock([.retractableGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston, .highPerformance])
        }
        if isChampion, ["7AC", "7BCM", "7CCM", "7DC", "7EC", "7ECA", "7FC", "7GCAA", "7GCBC", "7HC", "7KCAB", "8KCAB", "8GCBC"].contains(code) {
            if code != "7FC" { stock([.tailwheel, .fixedGear, .piston]) }
            else { stock([.tricycleGear, .fixedGear, .piston]) }
            if ["7AC", "7ECA", "7GCAA", "7GCBC"].contains(code) { stock([.fixedPitchPropeller]); set(.complex, false) }
            if ["7GCBC", "8GCBC"].contains(code) { set(.flaps) }
            if ["8KCAB", "8GCBC"].contains(code) { stock([.constantSpeedPropeller, .controllablePitchPropeller]) }
        }
        if isCirrus, ["SR20", "SR22", "SR22T"].contains(code) {
            stock([.fixedGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston]); set(.complex, false)
            if code == "SR22" { result.horsepower = 310 }; if code == "SR22T" { result.horsepower = 315 }
        }
        if isDiamond {
            if ["DA20", "DA20A1", "DA20C1"].contains(code) { stock([.fixedGear, .tricycleGear, .flaps, .piston]); set(.complex, false) }
            if code == "DA20C1" { set(.fixedPitchPropeller) }
            if code == "DA20A1" { stock([.constantSpeedPropeller, .controllablePitchPropeller]) }
            if ["DA40", "DA40NG", "DA40D", "DA40XLT", "DA40XL"].contains(code) {
                stock([.fixedGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston]); set(.complex, false)
            }
            if ["DA42", "DA42NG", "DA42VI", "DA42L360", "DA62", "DA50RG"].contains(code) {
                stock([.retractableGear, .tricycleGear, .constantSpeedPropeller, .controllablePitchPropeller, .flaps, .piston])
            }
            if ["DA40NG", "DA40XLT", "DA42NG", "DA42VI", "DA62", "DA50RG"].contains(code) { stock([.glassCockpit, .pfd, .mfd, .gps]) }
            if code == "DA50RG" || (code == "DA42VI" && (matchingInfo?.manufactureYear ?? 0) >= 2025) {
                stock([.twoAxisAutopilot]) // Current factory standard; older optional installations stay unknown.
            }
        }
        if maker.contains("ROBINSON") {
            if ["R22", "R22BETA", "R22MARINER", "R44", "R44II", "R44CADET", "R44RAVEN", "R44RAVENII", "R66"].contains(code) {
                stock([.skids, .fixedGear]); set(.complex, false); set(.highPerformance, false)
                stock(code == "R66" ? [.turboshaft] : [.piston])
                if code != "R66" { set(.robinsonSFAR73) }
            }
        }
        // A controllable-pitch or constant-speed propeller alone does not establish
        // the manual control required by the sport-pilot rule in 14 CFR 61.331(b).
        // Use known conventional stock installations; leave unknown controls unset.
        if result.values[AircraftFeature.constantSpeedPropeller.rawValue] == true {
            if isCessna || isPiper || maker.contains("BEECH") || isChampion
                || (isDiamond && ["DA20A1", "DA40XLT", "DA40XL", "DA42L360"].contains(code)) {
                set(.manualControllablePitchPropeller)
            }
        }
        if isDiamond, ["DA40NG", "DA40D", "DA42NG", "DA42VI", "DA62", "DA50RG"].contains(code) {
            set(.manualControllablePitchPropeller, false) // Automatic engine/propeller control.
        }
        if let reference {
            sources.append("FAA model reference")
            if reference.configuration == "3" { set(.amphibious) }
            if reference.weightClass == "3" { set(.largeAircraft) }
            if reference.weightClass == "1" { set(.largeAircraft, false) }
            // CLASS 2 includes exactly 12,500 lb. It cannot establish a >12,500-lb feature.
        }
        var engineType = matchingInfo?.engineType ?? ""
        if engineType.isEmpty { engineType = engine?.type ?? reference?.engineType ?? "" }
        var detectedEngine: AircraftFeature?
        switch AircraftReference.key(engineType) {
        case "1", "7", "8", "RECIPROCATING", "PISTON", "2CYCLE", "4CYCLE": detectedEngine = .piston
        case "2", "TURBOPROP": detectedEngine = .turboprop
        case "3", "TURBOSHAFT": detectedEngine = .turboshaft
        case "4", "TURBOJET": detectedEngine = .turbojet
        case "5", "TURBOFAN": detectedEngine = .turbofan
        case "10", "ELECTRIC": detectedEngine = .electric
        case "11", "ROTARY": detectedEngine = .rotaryEngine
        default: break
        }
        if let detectedEngine {
            set(detectedEngine)
            for alternative in detectedEngine.alternatives { set(alternative, false) }
        }
        // Registry series-level ratings can describe multiple engine subvariants.
        // Use the exact engine rating or the known airframe rating, never add twin-engine power.
        // FAA ENGINE's rating column can contain pounds of thrust for jets.
        // Jet thrust must never be treated as horsepower or as a high-performance endorsement.
        if detectedEngine == .turbojet || detectedEngine == .turbofan {
            result.horsepower = nil
            result.values.removeValue(forKey: AircraftFeature.highPerformance.rawValue)
        } else if !(matchingInfo?.engineModel ?? "").uppercased().contains("SER"), let hp = engine?.horsepower, hp > 0 {
            result.horsepower = hp
        }
        if airplane, let hp = result.horsepower { set(.highPerformance, hp > 200) }
        if airplane, let matchingInfo, let evidence = matchingInfo.modelEquipment,
           evidence.modelIdentity == AircraftModelLookup.identity(matchingInfo), evidence.category == category,
           AircraftFeatures.derived(result.values, category: category)["complex"] == nil {
            // Supplement missing stock equipment only. Installed avionics are not
            // inferred from this public make/model catalog.
            let allowed: Set<String> = ["complex", "flaps", "retractableGear", "controllablePitchPropeller"]
            for (key, value) in evidence.features where allowed.contains(key) && value && result.values[key] == nil {
                result.values[key] = true
            }
            sources.append(evidence.sourceName)
            result.modelSourceURL = evidence.sourceURL
        }
        if matchingInfo != nil { sources.insert("FAA registry", at: 0) }
        let classification = (matchingInfo?.airworthinessClass ?? "").uppercased()
        if classification == "STANDARD" { set(.standardAirworthiness) }
        if classification == "EXPERIMENTAL" { set(.experimental) }
        if classification == "RESTRICTED" { set(.restricted) }
        if classification == "LIGHT SPORT" || classification == "LIGHT-SPORT" { set(.specialLightSport) }
        let certification = (matchingInfo?.certificationCategory ?? "").uppercased()
        if certification.contains("UTILITY") { set(.utilityCategory) }
        if certification.contains("ACROBATIC") || certification.contains("AEROBATIC") { set(.aerobaticCategory) }
        if sea { // Do not assume a landplane's wheel arrangement is present on floats.
            for feature in [AircraftFeature.tricycleGear, .tailwheel, .fixedGear, .retractableGear] { result.values.removeValue(forKey: feature.rawValue) }
            result.values.removeValue(forKey: AircraftFeature.complex.rawValue)
        }
        result.values = derived(result.values, category: category, aircraftType: matchingInfo?.aircraftType ?? reference?.type ?? "")
        result.source = sources.isEmpty ? "Equipment could not be determined for this model." : Array(NSOrderedSet(array: sources)).compactMap { $0 as? String }.joined(separator: " · ")
        return result
    }
    static func derived(_ input: [String: Bool], category: String, aircraftType: String = "") -> [String: Bool] {
        var values = input
        func yes(_ key: AircraftFeature) -> Bool { values[key.rawValue] == true }
        let airplane = ["ASEL", "ASES", "AMEL", "AMES"].contains(category) || ["4", "5"].contains(aircraftType)
        if yes(.constantSpeedPropeller) { values[AircraftFeature.controllablePitchPropeller.rawValue] = true }
        if yes(.manualControllablePitchPropeller) {
            values[AircraftFeature.controllablePitchPropeller.rawValue] = true
            values[AircraftFeature.fixedPitchPropeller.rawValue] = false
        }
        if [.turboprop, .turboshaft, .turbojet, .turbofan].contains(where: yes) { values[AircraftFeature.turbine.rawValue] = true }
        if yes(.piston) || yes(.electric) || yes(.rotaryEngine) { values[AircraftFeature.turbine.rawValue] = false }
        if airplane {
            let required: [AircraftFeature] = ["ASES", "AMES"].contains(category) ? [.flaps, .controllablePitchPropeller] : [.retractableGear, .flaps, .controllablePitchPropeller]
            if required.allSatisfy(yes) { values[AircraftFeature.complex.rawValue] = true }
            if required.contains(where: { values[$0.rawValue] == false }) { values[AircraftFeature.complex.rawValue] = false }
            if [.pfd, .mfd, .gps, .twoAxisAutopilot].allSatisfy(yes) { values[AircraftFeature.taa.rawValue] = true }
            if yes(.turbojet) || yes(.turbofan) || yes(.largeAircraft) { values[AircraftFeature.typeRatingRequired.rawValue] = true }
        }
        let type = AircraftReference.key(aircraftType)
        let lighterThanAir = ["2", "3"].contains(type) || ["BALLOON", "BLIMP", "DIRIGIBLE", "AIRSHIP"].contains { type.contains($0) }
        if (yes(.largeAircraft) && !lighterThanAir && !type.isEmpty)
            || type.contains("HYBRIDLIFT") || type.contains("POWEREDLIFT") || type == "H" {
            values[AircraftFeature.typeRatingRequired.rawValue] = true
        }
        return values
    }
}

struct AircraftEquipmentState {
    var detected: [String: Bool] = [:]
    var corrections: [String: Bool] = [:]
    var visible: Set<String> = []
    var category = "Unspecified"
    var source = ""
    var horsepower: Double? = nil
    var engines: Int? = nil
    var recordedFlight = false
    var modelSourceURL: URL? = nil
    var resetSavedCorrections = false
    var clearedCorrections: Set<String> = []
    var values: [String: Bool] {
        var result = detected.merging(corrections, uniquingKeysWith: { _, new in new })
        if !recordedFlight { result = AircraftFeatures.derived(result, category: category) }
        // An explicit false is a correction, not a missing value. Never lose it to inference.
        return result.merging(corrections, uniquingKeysWith: { _, new in new })
    }
    func selected(_ feature: AircraftFeature) -> Bool { values[feature.rawValue] == true }
    var rows: [AircraftFeature] { AircraftFeature.pilotFeatures.filter { selected($0) || visible.contains($0.rawValue) } }
    mutating func update(model: String, category: String, info: AircraftInfo?, saved: SavedAircraft?) {
        self.category = category
        guard !recordedFlight else { return }
        let detection = AircraftFeatures.detect(model, category: category, info: info)
        detected = detection.values
        horsepower = detection.horsepower; engines = detection.engines; source = detection.source
        modelSourceURL = detection.modelSourceURL
        // New files distinguish automatic values from user corrections. Legacy choices remain respected.
        let sameModel = saved.map { AircraftNames.display($0.model) == AircraftNames.display(model) } ?? false
        let remembered = !resetSavedCorrections ? saved?.equipmentCorrections ?? [:] : [:]
        corrections = remembered.merging(corrections, uniquingKeysWith: { _, current in current })
        if sameModel, saved?.category == category, let cached = saved?.detectedFeatures, info == nil {
            // Preserve earlier evidence during a network failure, but prefer fresh model evidence.
            // Retired operator avionics claims must not reappear from old automatic
            // caches. User-confirmed TAA remains in corrections; factory data is redetected.
            let avionics: Set<String> = ["taa", "glassCockpit", "pfd", "mfd", "gps", "twoAxisAutopilot"]
            let equipmentOnly = cached.filter { !avionics.contains($0.key) }
            detected = equipmentOnly.merging(detected, uniquingKeysWith: { _, new in new })
        }
    }
    mutating func useDetectedFeatures() {
        guard !recordedFlight else { return }
        clearedCorrections.formUnion(corrections.keys)
        resetSavedCorrections = true
        corrections = [:]; visible = []
    }
    // Explicit edits, their dependent features, and cleared corrections are
    // aircraft-wide. An unchanged recorded flight does not overwrite other flights.
    var synchronizedFeatures: [String: Bool] {
        let resolved = values
        var changes = corrections
        for (key, value) in resolved where detected[key] != value { changes[key] = value }
        for key in clearedCorrections { changes[key] = resolved[key] ?? false }
        return changes
    }
    mutating func choose(_ feature: AircraftFeature, enabled: Bool) {
        corrections[feature.rawValue] = enabled; visible.insert(feature.rawValue)
        if enabled {
            for alternative in feature.alternatives { corrections[alternative.rawValue] = false }
            var children: [AircraftFeature] = []
            if feature == .taa { children = [.glassCockpit, .pfd, .mfd, .gps, .twoAxisAutopilot] }
            if feature == .complex { children = ["ASES", "AMES"].contains(category) ? [.flaps, .controllablePitchPropeller] : [.retractableGear, .flaps, .controllablePitchPropeller] }
            if feature == .constantSpeedPropeller { children = [.controllablePitchPropeller] }
            if feature == .manualControllablePitchPropeller { children = [.controllablePitchPropeller] }
            if [.turboprop, .turboshaft, .turbojet, .turbofan].contains(feature) { children.append(.turbine) }
            if feature == .highAltitude { children.append(.pressurized) }
            for child in children {
                corrections[child.rawValue] = true
                for alternative in child.alternatives { corrections[alternative.rawValue] = false }
            }
        }
        if (!enabled && [.pfd, .mfd, .gps, .twoAxisAutopilot].contains(feature)) { corrections[AircraftFeature.taa.rawValue] = false }
        if !enabled && feature == .controllablePitchPropeller {
            corrections[AircraftFeature.constantSpeedPropeller.rawValue] = false
            corrections[AircraftFeature.manualControllablePitchPropeller.rawValue] = false
        }
        if !enabled && feature == .turbine {
            for engine in [AircraftFeature.turboprop, .turboshaft, .turbojet, .turbofan] { corrections[engine.rawValue] = false }
        }
        if !enabled && [.turboprop, .turboshaft, .turbojet, .turbofan].contains(feature),
           ![AircraftFeature.turboprop, .turboshaft, .turbojet, .turbofan].contains(where: selected) {
            corrections[AircraftFeature.turbine.rawValue] = false
        }
        if (!enabled && [.retractableGear, .flaps, .controllablePitchPropeller].contains(feature)) {
            if feature != .retractableGear || !["ASES", "AMES"].contains(category) { corrections[AircraftFeature.complex.rawValue] = false }
        }
        if enabled && feature == .fixedGear && !["ASES", "AMES"].contains(category) { corrections[AircraftFeature.complex.rawValue] = false }
        if enabled && feature == .fixedPitchPropeller { corrections[AircraftFeature.complex.rawValue] = false }
        if enabled && [.piston, .electric, .rotaryEngine].contains(feature) { corrections[AircraftFeature.turbine.rawValue] = false }
        if !enabled && feature == .pressurized { corrections[AircraftFeature.highAltitude.rawValue] = false }
    }
    static func recorded(_ flight: Flight) -> AircraftEquipmentState {
        var state = AircraftEquipmentState(category: flight.category, source: "Equipment recorded for this flight", recordedFlight: true)
        state.detected = Dictionary(uniqueKeysWithValues: AircraftFeature.allCases.map { ($0.rawValue, flight.hasAircraftFeature($0)) })
        return state
    }
    static func imported(_ flight: Flight, model: String, category: String,
                         info: AircraftInfo?, saved: SavedAircraft?) -> AircraftEquipmentState {
        var state = recorded(flight)
        state.category = category
        let detection = AircraftFeatures.detect(model, category: category, info: info ?? saved?.equipmentInfo)
        state.detected = state.detected.merging(detection.values, uniquingKeysWith: { _, registry in registry })
        if let saved {
            for (key, enabled) in saved.resolvedEquipmentFeatures {
                // An old unchecked default must not erase positive CSV evidence.
                // Explicit aircraft corrections, including false, still take priority.
                if !enabled, state.detected[key] == true, saved.featureCorrections?[key] == nil { continue }
                state.detected[key] = enabled
            }
            state.corrections = saved.featureCorrections ?? saved.equipmentCorrections.filter { $0.value }
        }
        state.horsepower = detection.horsepower; state.engines = detection.engines
        state.source = detection.source; state.modelSourceURL = detection.modelSourceURL
        return state
    }
    func aircraft(registration: String, model: String, category: String, previous: SavedAircraft?, info: AircraftInfo?) -> SavedAircraft {
        var saved = previous ?? SavedAircraft(registration: registration, model: model)
        saved.registration = registration; saved.model = AircraftNames.display(model); saved.category = category
        if !recordedFlight {
            saved.detectedFeatures = detected
            saved.featureCorrections = corrections
            saved.equipmentInfo = info ?? previous?.equipmentInfo
        } else if !corrections.isEmpty {
            saved.featureCorrections = saved.equipmentCorrections.merging(corrections, uniquingKeysWith: { _, new in new })
        }
        let resolved = recordedFlight ? (saved.detectedFeatures ?? [:]).merging(saved.equipmentCorrections, uniquingKeysWith: { _, new in new }) : values
        if !recordedFlight || !corrections.isEmpty {
            saved.complex = resolved["complex"]; saved.highPerformance = resolved["hp"]
            saved.taa = resolved["taa"]; saved.turbine = resolved["turbine"]
        }
        return saved
    }
    func apply(to flight: inout Flight) {
        let result = values
        flight.complex = result["complex"] == true; flight.highPerformance = result["hp"] == true; flight.taa = result["taa"] == true
        for feature in AircraftFeature.allCases where ![.complex, .highPerformance, .taa].contains(feature) {
            let key = feature == .turbine ? "turbine" : "aircraftFeature." + feature.rawValue
            if feature == .tailwheel { flight.facts.flags.remove("tailwheel") }
            if feature == .turbine { flight.facts.flags.remove("aircraftFeature.turbine") }
            if result[feature.rawValue] == true { flight.facts.flags.insert(key) } else { flight.facts.flags.remove(key) }
        }
    }
}

extension SavedAircraft {
    var equipmentCorrections: [String: Bool] {
        if let featureCorrections { return featureCorrections }
        var legacy: [String: Bool] = [:]
        if let complex { legacy["complex"] = complex }; if let highPerformance { legacy["hp"] = highPerformance }
        if let taa { legacy["taa"] = taa }; if let turbine { legacy["turbine"] = turbine }
        return legacy
    }
    var resolvedEquipmentFeatures: [String: Bool] {
        let corrections = equipmentCorrections
        let known = (detectedFeatures ?? [:]).merging(corrections, uniquingKeysWith: { _, edit in edit })
        return AircraftFeatures.derived(known, category: category ?? "Unspecified")
            .merging(corrections, uniquingKeysWith: { _, edit in edit })
    }
}

enum AircraftFeatureSync {
    @discardableResult static func apply(_ values: [String: Bool], registration: String,
                                        to flights: inout [Flight], explicitCSVCorrections: Set<String>? = nil) -> Bool {
        let target = AircraftNames.registration(registration)
        guard !target.isEmpty, !values.isEmpty else { return false }
        var changed = false
        for index in flights.indices where !flights[index].isDevice && flights[index].registration == target {
            for feature in AircraftFeature.allCases {
                guard let enabled = values[feature.rawValue], flights[index].hasAircraftFeature(feature) != enabled else { continue }
                if !enabled, flights[index].facts.text["csvSource"] != nil,
                   let explicitCSVCorrections, !explicitCSVCorrections.contains(feature.rawValue) { continue }
                switch feature {
                case .complex: flights[index].complex = enabled
                case .highPerformance: flights[index].highPerformance = enabled
                case .taa: flights[index].taa = enabled
                default:
                    let key = feature == .turbine ? "turbine" : "aircraftFeature." + feature.rawValue
                    if feature == .tailwheel { flights[index].facts.flags.remove("tailwheel") }
                    if feature == .turbine { flights[index].facts.flags.remove("aircraftFeature.turbine") }
                    if enabled { flights[index].facts.flags.insert(key) }
                    else { flights[index].facts.flags.remove(key) }
                }
                changed = true
            }
        }
        // Keep the original signature and confirmation receipts. Their existing
        // digest checks report any changed record instead of re-signing it.
        return changed
    }
    @discardableResult static func applySavedFeatures(_ aircraft: [SavedAircraft],
                                                     to flights: inout [Flight]) -> Bool {
        var changed = false
        for item in aircraft {
            if apply(item.resolvedEquipmentFeatures, registration: item.registration, to: &flights,
                     explicitCSVCorrections: Set((item.featureCorrections ?? [:]).keys)) { changed = true }
        }
        return changed
    }
}

extension Flight {
    func hasAircraftFeature(_ feature: AircraftFeature) -> Bool {
        guard !isDevice else { return false }
        switch feature {
        case .complex: return complex
        case .highPerformance: return highPerformance
        case .taa: return taa
        case .turbine: return facts.has("turbine") || facts.has("aircraftFeature.turbine")
        case .tailwheel: return facts.has("aircraftFeature.tailwheel") || facts.has("tailwheel")
        default: return facts.has("aircraftFeature." + feature.rawValue)
        }
    }
}

struct AircraftFeaturePicker: View {
    @EnvironmentObject var theme: AppTheme
    @Binding var equipment: AircraftEquipmentState
    @State private var expanded = false
    private func selection(_ feature: AircraftFeature) -> Binding<Bool> {
        Binding(get: { equipment.selected(feature) }, set: { equipment.choose(feature, enabled: $0) })
    }
    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            ForEach(equipment.rows) { feature in
                Toggle(feature.title, isOn: selection(feature)).tint(theme.accent)
            }
            if !equipment.source.isEmpty {
                Text(equipment.source).font(.caption).foregroundStyle(theme.muted)
            }
            if let url = equipment.modelSourceURL {
                Link("View aircraft equipment source", destination: url).font(.caption).foregroundStyle(theme.cyan)
            }
            if equipment.horsepower != nil || equipment.engines != nil {
                HStack(spacing: 14) {
                    if let hp = equipment.horsepower { Text("\(Int(hp)) hp per engine") }
                    if let count = equipment.engines { Text("\(count) \(count == 1 ? "engine" : "engines")") }
                }.font(.caption).foregroundStyle(theme.muted)
            }
            Button {
                withAnimation(.easeInOut(duration: 0.3)) { expanded.toggle() }
            } label: {
                HStack {
                    Text("Additional aircraft features").fontWeight(.semibold)
                    Spacer(); Image(systemName: "chevron.down").rotationEffect(.degrees(expanded ? 180 : 0))
                }.contentShape(Rectangle())
            }.buttonStyle(.plain).foregroundStyle(theme.accent)
                .accessibilityValue(expanded ? "Expanded" : "Collapsed")
            if expanded {
                Text("Select a relevant feature that wasn't detected, or correct a listed feature. Your selections are remembered for this aircraft.")
                    .font(.caption).foregroundStyle(theme.muted)
                if !equipment.recordedFlight && !equipment.corrections.isEmpty {
                    Button("Use detected features") { equipment.useDetectedFeatures() }
                        .foregroundStyle(theme.cyan)
                    Text("Clears your saved feature corrections for this aircraft when you save.")
                        .font(.caption).foregroundStyle(theme.muted)
                }
                ForEach(AircraftFeature.pilotGroups, id: \.self) { group in
                    Text(group).font(.caption.weight(.semibold)).foregroundStyle(theme.cyan).padding(.top, 6)
                    ForEach(AircraftFeature.pilotFeatures.filter { $0.pilotGroup == group }) { feature in
                        Button { equipment.choose(feature, enabled: !equipment.selected(feature)) } label: {
                            HStack(spacing: 10) {
                                Image(systemName: equipment.selected(feature) ? "checkmark.square.fill" : "square")
                                    .foregroundStyle(equipment.selected(feature) ? theme.accent : theme.muted)
                                Text(feature.title).foregroundStyle(theme.text).multilineTextAlignment(.leading)
                                Spacer(minLength: 0)
                            }.padding(.vertical, 5).contentShape(Rectangle())
                        }.buttonStyle(.plain).accessibilityValue(equipment.selected(feature) ? "Selected" : "Not selected")
                    }
                }
                Text("Features describe the aircraft. Training and instructor endorsements are recorded separately. Select TAA only when its required displays, GPS moving map and integrated two-axis autopilot are installed.")
                    .font(.caption).foregroundStyle(theme.muted)
            }
        }.font(.subheadline).logbookCard()
    }
}

nonisolated struct AircraftPhotoQuality: Codable, Sendable {
    static let currentVersion = 4
    let width: Int
    let height: Int
    let sharpness: Double
    let differenceHash: UInt64
    let averageHash: UInt64
    let version: Int
    var sufficientPixels: Bool { max(width, height) >= 1600 && min(width, height) >= 900 }
    // This rejects visibly soft/upscaled previews. It is a quality heuristic,
    // not a claim that pixel count or a single score can prove a photo is sharp.
    var acceptable: Bool { sufficientPixels && sharpness >= 20 && version == Self.currentVersion }
    var rank: Double { acceptable ? log1p(sharpness) * sqrt(Double(width) * Double(height)) : 0 }
    func sameImage(as other: AircraftPhotoQuality) -> Bool {
        (differenceHash ^ other.differenceHash).nonzeroBitCount <= 2 &&
        (averageHash ^ other.averageHash).nonzeroBitCount <= 2
    }
    static func edgeEnergy(_ pixels: [UInt8], width: Int, height: Int) -> Double {
        guard width > 2, height > 2, pixels.count == width * height else { return 0 }
        var sum = 0.0, square = 0.0, count = 0.0
        for y in 1..<(height - 1) {
            for x in 1..<(width - 1) {
                let i = y * width + x
                let edge = Double(Int(pixels[i - 1]) + Int(pixels[i + 1]) + Int(pixels[i - width]) + Int(pixels[i + width]) - 4 * Int(pixels[i]))
                sum += edge; square += edge * edge; count += 1
            }
        }
        return max(0, square / count - pow(sum / count, 2))
    }
}
nonisolated struct AircraftPhotoCandidate: Sendable {
    let url: URL
    let page: URL
    let credit: String
    let license: URL?
    let date: Date?
}
nonisolated enum AircraftPhotoSource {
    static func matchesTail(_ text: String, registration: String) -> Bool {
        let normalized = text.uppercased().replacingOccurrences(of: "-", with: "").replacingOccurrences(of: "_", with: " ")
        let tail = NSRegularExpression.escapedPattern(for: registration.replacingOccurrences(of: "-", with: ""))
        return normalized.range(of: "(?<![A-Z0-9])" + tail + "(?![A-Z0-9])", options: .regularExpression) != nil
    }
    static func airportURL(_ raw: String, base: URL) -> URL? {
        let text = WebData.plainEntities(raw).replacingOccurrences(of: "\\/", with: "/")
        guard let resolved = URL(string: text, relativeTo: base)?.absoluteURL,
              var components = URLComponents(url: resolved, resolvingAgainstBaseURL: true),
              let host = components.host?.lowercased(), ["airport-data.com", "www.airport-data.com", "image.airport-data.com"].contains(host),
              components.user == nil, components.password == nil, components.port == nil,
              ["http", "https"].contains(components.scheme?.lowercased() ?? "") else { return nil }
        components.scheme = "https"; components.fragment = nil
        if host == "www.airport-data.com" { components.host = "airport-data.com" }
        if components.path.hasSuffix(".html") { components.path = String(components.path.dropLast(5)) }
        return components.url
    }
    static func links(_ html: String, base: URL) -> [URL] {
        var seen = Set<String>()
        return WebData.matches(#"href\s*=\s*["']([^"']+)["']"#, in: html).compactMap {
            guard let url = airportURL($0, base: base), seen.insert(url.absoluteString).inserted else { return nil }
            return url
        }
    }
    static func isPhotoPage(_ url: URL) -> Bool {
        url.host == "airport-data.com" && url.path.range(of: #"^/aircraft/photo/[0-9]+$"#, options: .regularExpression) != nil
    }
    static func isGallery(_ url: URL, registration: String) -> Bool {
        guard url.host == "airport-data.com" else { return false }
        let parts = url.path.split(separator: "/")
        guard parts.count >= 3, parts[0] == "aircraft", parts[1] == "photos" else { return false }
        let galleryID = String(parts[2])
        let decodedID = galleryID.removingPercentEncoding ?? galleryID
        let tail = decodedID.split(separator: ":").first.map(String.init) ?? ""
        return tail.uppercased().replacingOccurrences(of: "-", with: "") == registration.uppercased().replacingOccurrences(of: "-", with: "")
    }
    static func photoPages(_ html: String, base: URL) -> [URL] { links(html, base: base).filter(isPhotoPage) }
    static func galleries(_ html: String, base: URL, registration: String) -> [URL] {
        links(html, base: base).filter { isGallery($0, registration: registration) }
    }
    static func detail(_ encoded: String, page: URL, registration: String) -> AircraftPhotoCandidate? {
        let html = WebData.plainEntities(encoded)
        let photoID = page.lastPathComponent
        func verifiedImage(_ raw: String) -> URL? {
            guard let url = airportURL(raw, base: page), url.host == "image.airport-data.com",
                  url.path.hasPrefix("/aircraft/"), !url.path.lowercased().contains("thumb"),
                  url.deletingPathExtension().lastPathComponent == photoID else { return nil }
            return url
        }
        let scripts = WebData.matches(#"<script\b[^>]*type\s*=\s*["']application/ld\+json["'][^>]*>(.*?)</script>"#, in: html)
        func imageObjects(_ value: Any) -> [[String: Any]] {
            if let list = value as? [Any] { return list.flatMap(imageObjects) }
            guard let object = value as? [String: Any] else { return [] }
            let type = object["@type"] as? String ?? ""
            if type == "ImageObject" { return [object] }
            return (object["@graph"] as? [Any] ?? []).flatMap(imageObjects)
        }
        for script in scripts {
            guard let data = script.data(using: .utf8), let value = try? JSONSerialization.jsonObject(with: data) else { continue }
            for image in imageObjects(value) {
                let identity = [image["name"] as? String, image["description"] as? String].compactMap { $0 }.joined(separator: " ")
                guard matchesTail(identity, registration: registration), let raw = image["contentUrl"] as? String, let url = verifiedImage(raw) else { continue }
                let creator = (image["creator"] as? [String: Any])?["name"] as? String
                let credit = image["creditText"] as? String ?? creator ?? "Airport-Data photographer"
                let date = (image["dateCreated"] as? String).flatMap { ISO8601DateFormatter().date(from: $0 + "T12:00:00Z") }
                return AircraftPhotoCandidate(url: url, page: page, credit: "Airport-Data · " + WebData.plain(credit),
                    license: (image["license"] as? String).flatMap(URL.init(string:)), date: date)
            }
        }
        // Legacy pages: validate the primary heading/description, not the related-photo grid.
        let primary = WebData.matches(#"<h1\b[^>]*>(.*?)</h1>"#, in: html).first ??
            WebData.matches(#"<title\b[^>]*>(.*?)</title>"#, in: html).first ?? ""
        guard matchesTail(WebData.plain(primary), registration: registration),
              let raw = WebData.matches(#"["']((?:https:)?//image\.airport-data\.com/aircraft/[^"'<>\s]+)["']"#, in: html).first,
              let url = verifiedImage(raw) else { return nil }
        let photographer = WebData.matches(#"photo by\s+([^<"\n]+)"#, in: primary).first ?? "Airport-Data photographer"
        return AircraftPhotoCandidate(url: url, page: page, credit: "Airport-Data · " + WebData.plain(photographer), license: nil, date: nil)
    }
}
nonisolated struct ProcessedAircraftPhoto: Sendable {
    let data: Data
    let quality: AircraftPhotoQuality
}
actor AircraftPhotoProcessor {
    static let shared = AircraftPhotoProcessor()
    func process(_ data: Data) -> ProcessedAircraftPhoto? {
        autoreleasepool {
            guard let source = CGImageSourceCreateWithData(data as CFData, nil),
                  let image = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                    kCGImageSourceCreateThumbnailFromImageAlways: true, kCGImageSourceCreateThumbnailWithTransform: true,
                    kCGImageSourceThumbnailMaxPixelSize: 3200, kCGImageSourceShouldCacheImmediately: true
                  ] as CFDictionary), max(image.width, image.height) >= 1600,
                  min(image.width, image.height) >= 900 else { return nil }
            func gray(_ width: Int, _ height: Int) -> [UInt8] {
                var pixels = [UInt8](repeating: 0, count: width * height)
                pixels.withUnsafeMutableBytes { buffer in
                    if let context = CGContext(data: buffer.baseAddress, width: width, height: height, bitsPerComponent: 8,
                        bytesPerRow: width, space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGImageAlphaInfo.none.rawValue) {
                        context.interpolationQuality = .high; context.draw(image, in: CGRect(x: 0, y: 0, width: width, height: height))
                    }
                }
                return pixels
            }
            let sampleScale = 320.0 / Double(max(image.width, image.height))
            let sampleWidth = max(32, Int(Double(image.width) * sampleScale))
            let sampleHeight = max(32, Int(Double(image.height) * sampleScale))
            let sharpness = AircraftPhotoQuality.edgeEnergy(gray(sampleWidth, sampleHeight), width: sampleWidth, height: sampleHeight)
            let difference = gray(9, 8), average = gray(8, 8), mean = Double(average.reduce(0) { $0 + Int($1) }) / 64
            var differenceHash: UInt64 = 0, averageHash: UInt64 = 0
            for y in 0..<8 {
                for x in 0..<8 {
                    let bit = UInt64(1) << UInt64(y * 8 + x)
                    if difference[y * 9 + x] > difference[y * 9 + x + 1] { differenceHash |= bit }
                    if Double(average[y * 8 + x]) > mean { averageHash |= bit }
                }
            }
            let quality = AircraftPhotoQuality(width: image.width, height: image.height, sharpness: sharpness,
                differenceHash: differenceHash, averageHash: averageHash, version: AircraftPhotoQuality.currentVersion)
            guard quality.acceptable else { return nil }
            let output = NSMutableData()
            guard let destination = CGImageDestinationCreateWithData(output, "public.jpeg" as CFString, 1, nil) else { return nil }
            CGImageDestinationAddImage(destination, image, [kCGImageDestinationLossyCompressionQuality: 0.95] as CFDictionary)
            guard CGImageDestinationFinalize(destination) else { return nil }
            return ProcessedAircraftPhoto(data: output as Data, quality: quality)
        }
    }
}
struct AircraftGalleryItem: Identifiable, Codable {
    var id = UUID()
    var filename: String
    var addedAt = Date()
    var userAdded: Bool
    var credit: String
    var link: URL? = nil
    var checksum: String? = nil
    var quality: AircraftPhotoQuality? = nil
    var imageURL: URL? = nil
    var licenseURL: URL? = nil
    var photoDate: Date? = nil
}

@MainActor final class AircraftPhotos: ObservableObject {
    @Published private(set) var images: [String: UIImage] = [:]
    @Published private(set) var galleries: [String: [AircraftGalleryItem]] = [:]
    @Published private(set) var sources: [String: String] = [:]
    @Published private(set) var links: [String: URL] = [:]
    @Published private(set) var loading: Set<String> = []
    @Published var errorMessage: String?
    private var jobs: [String: Task<Void, Never>] = [:]
    private var retryAfter: [String: Date] = [:]
    @Published private(set) var lookupNotes: [String: String] = [:]
    private var hydrated: Set<String> = []
    private var unreadable: Set<String> = []
    private let imageCache: NSCache<NSString, UIImage> = {
        let cache = NSCache<NSString, UIImage>()
        cache.countLimit = 12
        cache.totalCostLimit = 96 * 1024 * 1024
        return cache
    }()
    private var folder: URL {
        let url = PhotoStore.folder.appendingPathComponent("Aircraft", isDirectory: true)
        try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }
    private func manifest(_ registration: String) -> URL {
        folder.appendingPathComponent(PhotoStore.safe(registration) + "-gallery.json")
    }
    func image(_ item: AircraftGalleryItem) -> UIImage? {
        if let cached = imageCache.object(forKey: item.filename as NSString) { return cached }
        guard let image = UIImage(contentsOfFile: folder.appendingPathComponent(item.filename).path) else { return nil }
        cacheImage(image, filename: item.filename)
        return image
    }
    private func cacheImage(_ image: UIImage, filename: String) {
        let pixels = image.size.width * image.scale * image.size.height * image.scale
        imageCache.setObject(image, forKey: filename as NSString, cost: Int(min(CGFloat(Int.max / 4), max(0, pixels))) * 4)
    }
    private func hydrate(_ registration: String) {
        guard !hydrated.contains(registration) else { return }
        hydrated.insert(registration)
        let url = manifest(registration)
        if FileManager.default.fileExists(atPath: url.path) {
            do { galleries[registration] = try JSONDecoder().decode([AircraftGalleryItem].self, from: Data(contentsOf: url)) }
            catch {
                unreadable.insert(registration)
                errorMessage = "The saved photo gallery for \(registration) could not be read. Its files have been retained."
            }
        } else {
            // Migrate the previous single-photo cache without replacing or deleting its image.
            let filename = PhotoStore.safe(registration) + ".jpg"
            if let image = UIImage(contentsOfFile: folder.appendingPathComponent(filename).path) {
                let credit = UserDefaults.standard.string(forKey: "photoCredit-" + registration) ?? "Your photo"
                let item = AircraftGalleryItem(filename: filename, userAdded: credit == "Your photo", credit: credit,
                    link: UserDefaults.standard.url(forKey: "photoLink-" + registration))
                cacheImage(image, filename: filename)
                _ = persist([item], registration: registration)
            } else { galleries[registration] = [] }
        }
        refreshCover(registration)
    }
    private func refreshCover(_ registration: String) {
        let first = (galleries[registration] ?? []).first { image($0) != nil }
        images[registration] = first.flatMap { image($0) }
        sources[registration] = first?.credit
        links[registration] = first?.link
    }
    @discardableResult private func persist(_ items: [AircraftGalleryItem], registration: String) -> Bool {
        guard !unreadable.contains(registration) else { errorMessage = "Restore this aircraft's unreadable gallery before changing its photos."; return false }
        do {
            let data = try JSONEncoder().encode(items)
            try data.write(to: manifest(registration), options: .atomic)
            galleries[registration] = items; refreshCover(registration)
            return true
        } catch { errorMessage = error.localizedDescription; return false }
    }
    func loadSaved(_ input: String) {
        let registration = AircraftNames.registration(input)
        if !registration.isEmpty { hydrate(registration) }
    }
    static func decodedPhoto(_ data: Data) -> UIImage? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let cg = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceThumbnailMaxPixelSize: 3200,
                kCGImageSourceShouldCacheImmediately: true
              ] as CFDictionary) else { return UIImage(data: data) }
        return UIImage(cgImage: cg)
    }
    @discardableResult func add(_ image: UIImage, registration input: String) -> Bool {
        let registration = AircraftNames.registration(input)
        guard !registration.isEmpty else { errorMessage = "Choose an aircraft before adding its photos."; return false }
        hydrate(registration)
        return savePhoto(image, registration: registration, userAdded: true, credit: "Your photo", link: nil)
    }
    static let maximumPhotos = 5
    func visibleItems(_ registration: String) -> [AircraftGalleryItem] {
        // Preserve old overflow photos on disk; every gallery displays at most five.
        Array((galleries[AircraftNames.registration(registration)] ?? []).prefix(Self.maximumPhotos))
    }
    static func isDetailQuality(_ image: UIImage) -> Bool {
        let width = image.size.width * image.scale, height = image.size.height * image.scale
        return max(width, height) >= 1600 && min(width, height) >= 900
    }
    private func publicGalleryComplete(_ registration: String) -> Bool {
        let items = visibleItems(registration)
        return items.count >= Self.maximumPhotos && items.allSatisfy { $0.userAdded || $0.quality?.acceptable == true }
    }
    private func savePhoto(_ image: UIImage, registration: String, userAdded: Bool, credit: String, link: URL?) -> Bool {
        guard !unreadable.contains(registration), let data = image.jpegData(compressionQuality: 0.95) else { return false }
        let checksum = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
        var items = galleries[registration] ?? []
        if let index = items.firstIndex(where: { $0.checksum == checksum }) {
            if userAdded {
                // An uploaded copy can be managed/deleted by its uploader, while
                // retaining the original public source attribution if present.
                if !items[index].userAdded {
                    guard items.filter(\.userAdded).count < Self.maximumPhotos else { return false }
                    items[index].userAdded = true
                    let item = items.remove(at: index); items.insert(item, at: 0)
                    return persist(items, registration: registration)
                }
                return makeCover(items[index].id, registration: registration)
            }
            return true
        }
        if userAdded && items.filter(\.userAdded).count >= Self.maximumPhotos {
            errorMessage = "An aircraft can have up to five photos. Delete one of your photos before adding another."; return false
        }
        // Upgrade a previously cached thumbnail using the same source page.
        if !userAdded, let link, let index = items.firstIndex(where: { !$0.userAdded && $0.link == link }) {
            if let existing = self.image(items[index]), Self.isDetailQuality(existing) { return true }
            items.remove(at: index)
        }
        if !userAdded {
            // Low-quality public images remain cached until a verified larger photo is available.
            items.removeAll { !$0.userAdded && self.image($0).map(Self.isDetailQuality) != true }
            guard items.count < Self.maximumPhotos else { return false }
        }
        let filename = PhotoStore.safe(registration) + "-" + UUID().uuidString + ".jpg"
        let url = folder.appendingPathComponent(filename)
        do { try data.write(to: url, options: .atomic) }
        catch { errorMessage = error.localizedDescription; return false }
        let item = AircraftGalleryItem(filename: filename, userAdded: userAdded, credit: credit, link: link, checksum: checksum)
        // Keep user photos first. A retry of the public lookup never replaces them.
        if userAdded {
            items.insert(item, at: 0)
            while items.count > Self.maximumPhotos, let index = items.lastIndex(where: { !$0.userAdded }) { items.remove(at: index) }
        } else { items.append(item) }
        cacheImage(image, filename: filename)
        if !persist(items, registration: registration) {
            imageCache.removeObject(forKey: filename as NSString); try? FileManager.default.removeItem(at: url); return false
        }
        return true
    }
    @discardableResult func makeCover(_ id: UUID, registration input: String) -> Bool {
        let registration = AircraftNames.registration(input); hydrate(registration)
        var items = galleries[registration] ?? []
        guard let index = items.firstIndex(where: { $0.id == id }) else { return false }
        let item = items.remove(at: index); items.insert(item, at: 0)
        return persist(items, registration: registration)
    }
    @discardableResult func delete(_ id: UUID, registration input: String) -> Bool {
        let registration = AircraftNames.registration(input); hydrate(registration)
        let items = galleries[registration] ?? []
        guard let item = items.first(where: { $0.id == id }), item.userAdded else { return false }
        guard persist(items.filter { $0.id != id }, registration: registration) else { return false }
        imageCache.removeObject(forKey: item.filename as NSString)
        try? FileManager.default.removeItem(at: folder.appendingPathComponent(item.filename))
        return true
    }
    func load(_ input: String, retry: Bool = false) async {
        let registration = AircraftNames.registration(input)
        guard !registration.isEmpty else { return }
        hydrate(registration)
        guard !unreadable.contains(registration) else { return }
        if let job = jobs[registration] { await job.value; return }
        if visibleItems(registration).filter(\.userAdded).count >= Self.maximumPhotos { return }
        let checked = UserDefaults.standard.double(forKey: "publicPhotoChecked-v4-" + registration)
        if !retry, publicGalleryComplete(registration), Date().timeIntervalSince1970 - checked < 7 * 86400 { return }
        if !retry, (retryAfter[registration] ?? .distantPast) > Date() { return }
        loading.insert(registration); lookupNotes[registration] = nil
        // Shared work survives scrolling away or switching tabs. A failed or
        // incomplete lookup can run again; it is not permanently marked attempted.
        let job = Task { @MainActor [weak self] in
            guard let self else { return }
            await self.fetchGallery(registration)
            self.loading.remove(registration); self.jobs.removeValue(forKey: registration)
            self.retryAfter[registration] = Date().addingTimeInterval(120)
            UserDefaults.standard.set(Date().timeIntervalSince1970, forKey: "publicPhotoChecked-v4-" + registration)
        }
        jobs[registration] = job
        await job.value
    }
    private func savePublic(_ photo: ProcessedAircraftPhoto, candidate: AircraftPhotoCandidate, registration: String) -> Bool {
        guard !unreadable.contains(registration), photo.quality.acceptable else { return false }
        var items = galleries[registration] ?? []
        let checksum = SHA256.hash(data: photo.data).map { String(format: "%02x", $0) }.joined()
        let match = items.firstIndex { item in
            item.checksum == checksum || item.link == candidate.page || item.quality.map { photo.quality.sameImage(as: $0) } == true
        }
        if let match, items[match].userAdded { return true }
        if let match, let quality = items[match].quality, quality.acceptable, quality.rank >= photo.quality.rank * 0.95 { return true }
        let existingID = match.map { items[$0].id }
        if let match { items.remove(at: match) }
        // Preserve the old image files for recovery. The manifest switches to
        // the verified original only after its download and quality checks pass.
        items.removeAll { !$0.userAdded && $0.quality?.acceptable != true }
        if items.count >= Self.maximumPhotos {
            let publicIndices = items.indices.filter { !items[$0].userAdded }
            guard let worst = publicIndices.min(by: { (items[$0].quality?.rank ?? 0) < (items[$1].quality?.rank ?? 0) }) else { return false }
            let newer = candidate.date.map { $0 > (items[worst].photoDate ?? .distantPast) } ?? false
            guard newer || photo.quality.rank > (items[worst].quality?.rank ?? 0) * 1.15 else { return true }
            items.remove(at: worst)
        }
        let filename = PhotoStore.safe(registration) + "-" + UUID().uuidString + ".jpg"
        let url = folder.appendingPathComponent(filename)
        do { try photo.data.write(to: url, options: .atomic) } catch { errorMessage = error.localizedDescription; return false }
        var item = AircraftGalleryItem(filename: filename, userAdded: false, credit: candidate.credit, link: candidate.page, checksum: checksum)
        if let existingID { item.id = existingID }
        item.quality = photo.quality; item.imageURL = candidate.url; item.licenseURL = candidate.license; item.photoDate = candidate.date
        let insertion = items.firstIndex { !$0.userAdded && (candidate.date ?? .distantPast) > ($0.photoDate ?? .distantPast) }
        items.insert(item, at: insertion ?? items.count)
        guard persist(items, registration: registration) else { try? FileManager.default.removeItem(at: url); return false }
        return true
    }
    private func fetchGallery(_ registration: String) async {
        let initiallyComplete = publicGalleryComplete(registration)
        var photoPages: [URL] = [], galleries: [URL] = [], visitedGalleries = Set<String>()
        let profile = URL(string: "https://airport-data.com/aircraft/\(registration)")!
        if let data = try? await WebData.data(profile), let html = String(data: data, encoding: .utf8) {
            photoPages = AircraftPhotoSource.photoPages(html, base: profile)
            galleries = AircraftPhotoSource.galleries(html, base: profile, registration: registration)
        }
        // Registration-only lookup works even when FAA model lookup is offline.
        if photoPages.isEmpty, let api = URL(string: "https://airport-data.com/api/ac_thumb.json?r=\(registration)&n=10"),
           let json = await WebData.json(api), let rows = json["data"] as? [[String: Any]] {
            photoPages += rows.compactMap { row in
                guard let raw = row["link"] as? String, let url = AircraftPhotoSource.airportURL(raw, base: profile),
                      AircraftPhotoSource.isPhotoPage(url) else { return nil }
                return url
            }
        }
        if galleries.isEmpty { galleries = [URL(string: "https://airport-data.com/aircraft/photos/\(registration)/")!] }
        // Follow actual full-gallery and pagination links. Scope them to the
        // same registration/airframe gallery; never crawl unrelated galleries.
        while !galleries.isEmpty, visitedGalleries.count < 4 {
            let page = galleries.removeFirst()
            guard visitedGalleries.insert(page.absoluteString).inserted else { continue }
            guard let data = try? await WebData.data(page), let html = String(data: data, encoding: .utf8) else { continue }
            photoPages += AircraftPhotoSource.photoPages(html, base: page)
            let scope = page.path.split(separator: "/").prefix(3).joined(separator: "/")
            let next = AircraftPhotoSource.galleries(html, base: page, registration: registration).filter {
                $0.path.split(separator: "/").prefix(3).joined(separator: "/") == scope && !visitedGalleries.contains($0.absoluteString)
            }
            galleries += next
        }
        var seen = Set<String>()
        photoPages = Array(photoPages.filter { seen.insert($0.absoluteString).inserted }.prefix(24))
        // At most three originals are in flight. Decode, sharpness analysis and
        // perceptual hashing run on their own actor, not the UI actor.
        await withTaskGroup(of: (AircraftPhotoCandidate?, ProcessedAircraftPhoto?).self) { group in
            var iterator = photoPages.makeIterator()
            func add(_ page: URL) {
                group.addTask {
                    guard let data = try? await WebData.data(page), let html = String(data: data, encoding: .utf8),
                          let candidate = AircraftPhotoSource.detail(html, page: page, registration: registration),
                          let original = try? await WebData.data(candidate.url) else { return (nil, nil) }
                    return (candidate, await AircraftPhotoProcessor.shared.process(original))
                }
            }
            for _ in 0..<min(3, photoPages.count) { if let page = iterator.next() { add(page) } }
            while let (candidate, processed) = await group.next() {
                if let candidate, let processed { _ = savePublic(processed, candidate: candidate, registration: registration) }
                if publicGalleryComplete(registration) && !initiallyComplete { group.cancelAll(); break }
                if let page = iterator.next() { add(page) }
            }
        }
        if publicGalleryComplete(registration) { return }
        // Commons provides independently licensed originals as a fallback.
        var query = URLComponents(string: "https://commons.wikimedia.org/w/api.php")!
        query.queryItems = [
            URLQueryItem(name: "action", value: "query"), URLQueryItem(name: "generator", value: "search"),
            URLQueryItem(name: "gsrsearch", value: "\"\(registration)\""), URLQueryItem(name: "gsrnamespace", value: "6"),
            URLQueryItem(name: "gsrlimit", value: "15"), URLQueryItem(name: "prop", value: "imageinfo"),
            URLQueryItem(name: "iiprop", value: "url|size|timestamp|extmetadata"), URLQueryItem(name: "iiurlwidth", value: "2400"),
            URLQueryItem(name: "format", value: "json")
        ]
        if let url = query.url, let json = await WebData.json(url),
           let q = json["query"] as? [String: Any], let pages = q["pages"] as? [String: Any] {
            func photoDate(_ value: Any) -> Date {
                guard let page = value as? [String: Any], let info = (page["imageinfo"] as? [[String: Any]])?.first else { return .distantPast }
                let metadata = info["extmetadata"] as? [String: [String: Any]]
                let original = WebData.plain(metadata?["DateTimeOriginal"]?["value"] as? String ?? "")
                let formatter = DateFormatter(); formatter.locale = Locale(identifier: "en_US_POSIX"); formatter.isLenient = false
                for format in ["yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd", "d MMMM yyyy", "MMMM d, yyyy", "yyyy:MM:dd HH:mm:ss"] {
                    formatter.dateFormat = format
                    if let date = formatter.date(from: original) { return date }
                }
                return ISO8601DateFormatter().date(from: info["timestamp"] as? String ?? "") ?? .distantPast
            }
            let candidates = pages.values.sorted { photoDate($0) > photoDate($1) }
            for value in candidates {
                guard let page = value as? [String: Any], let title = page["title"] as? String,
                      AircraftPhotoSource.matchesTail(title, registration: registration),
                      let infos = page["imageinfo"] as? [[String: Any]], let info = infos.first,
                      let text = info["url"] as? String, let photoURL = URL(string: text) else { continue }
                if publicGalleryComplete(registration) { break }
                let metadata = (info["extmetadata"] as? [String: [String: Any]]) ?? [:]
                let artist = WebData.plain(metadata["Artist"]?["value"] as? String ?? "Wikimedia Commons")
                let license = (metadata["LicenseShortName"]?["value"] as? String) ?? ""
                let credit = [artist, license].filter { !$0.isEmpty }.joined(separator: " · ")
                guard !license.isEmpty, photoURL.host == "upload.wikimedia.org",
                      let page = (info["descriptionurl"] as? String).flatMap(URL.init(string:)),
                      let data = try? await WebData.data(photoURL), let photo = await AircraftPhotoProcessor.shared.process(data) else { continue }
                let candidate = AircraftPhotoCandidate(url: photoURL, page: page, credit: credit,
                    license: (metadata["LicenseUrl"]?["value"] as? String).flatMap(URL.init(string:)), date: photoDate(value))
                _ = savePublic(photo, candidate: candidate, registration: registration)
            }
        }
        let verified = visibleItems(registration).filter { $0.userAdded || $0.quality?.acceptable == true }.count
        if verified < Self.maximumPhotos {
            if verified == 0 {
                lookupNotes[registration] = visibleItems(registration).isEmpty ? "No suitable public photo was available. You can add your own." :
                    "No sharper public original was available. Your saved photo is retained."
            } else { lookupNotes[registration] = "Found \(verified) usable photos. Retry lookup or add your own." }
        }
    }
}

struct AircraftPhoto: View {
    @EnvironmentObject var photos: AircraftPhotos
    @EnvironmentObject var theme: AppTheme
    let registration: String
    var body: some View {
        let placeholderColor = theme.raised
        let loadingColor = theme.accent
        let captionColor = theme.muted
        return GeometryReader { geometry in
            ZStack {
                placeholderColor
                if let image = photos.images[AircraftNames.registration(registration)] {
                    Image(uiImage: image).resizable().scaledToFill()
                        .frame(width: geometry.size.width, height: geometry.size.height).clipped()
                } else if photos.loading.contains(AircraftNames.registration(registration)) {
                    ProgressView().tint(loadingColor)
                } else {
                    VStack(spacing: 5) {
                        Image(systemName: "photo").font(.title3)
                        if geometry.size.width > 130 { Text("Add an aircraft photo").font(.caption) }
                    }.foregroundStyle(captionColor)
                }
            }
        }.clipped().task(id: registration) { await photos.load(registration) }
    }
}

struct AircraftGallery: View {
    @EnvironmentObject var photos: AircraftPhotos
    @EnvironmentObject var theme: AppTheme
    let registration: String
    var editable = true
    var height: CGFloat = 220
    @State private var selected: UUID?
    @State private var photoItems: [PhotosPickerItem] = []
    @State private var importing = false
    @State private var problem: String?
    private var reg: String { AircraftNames.registration(registration) }
    private var items: [AircraftGalleryItem] { photos.visibleItems(reg) }
    private var current: AircraftGalleryItem? { items.first { $0.id == selected } ?? items.first }
    var body: some View {
        let placeholderColor = theme.raised
        let captionColor = theme.muted
        return VStack(alignment: .leading, spacing: 10) {
            if items.isEmpty {
                AircraftPhoto(registration: reg).frame(height: height).clipShape(RoundedRectangle(cornerRadius: 22))
            } else {
                TabView(selection: $selected) {
                    ForEach(items) { item in
                        GeometryReader { geometry in
                            if let image = photos.image(item) {
                                Image(uiImage: image).resizable().scaledToFill()
                                    .frame(width: geometry.size.width, height: geometry.size.height).clipped()
                            } else { placeholderColor.overlay(Text("Photo unavailable").foregroundStyle(captionColor)) }
                        }.tag(Optional(item.id))
                    }
                }.tabViewStyle(.page(indexDisplayMode: items.count > 1 ? .always : .never))
                    .frame(height: height).clipShape(RoundedRectangle(cornerRadius: 22))
            }
            if let item = current {
                HStack(spacing: 8) {
                    if let link = item.link { Link(item.credit, destination: link).lineLimit(1) }
                    else { Text(item.credit).foregroundStyle(theme.muted) }
                    Spacer()
                    Text("\((items.firstIndex { $0.id == item.id } ?? 0) + 1) / \(items.count)").foregroundStyle(theme.muted)
                }.font(.caption)
                if !item.userAdded, item.quality?.acceptable != true {
                    Text("This older saved photo has not passed the new quality check. Retry lookup to check for a sharper original.")
                        .font(.caption2).foregroundStyle(theme.muted)
                }
            }
            if photos.loading.contains(reg) {
                HStack(spacing: 8) { ProgressView(); Text("Checking original photos…") }
                    .font(.caption).foregroundStyle(theme.muted)
            } else if let note = photos.lookupNotes[reg] {
                Text(note).font(.caption2).foregroundStyle(theme.muted)
            }
            if editable {
                controls
                if let item = current, item.userAdded {
                    Button("Delete this photo", role: .destructive) {
                        if !photos.delete(item.id, registration: reg) { problem = photos.errorMessage ?? "The photo could not be removed." }
                    }.font(.caption)
                }
            }
        }
        .task(id: reg) { selected = nil; await photos.load(reg) }
        .onChange(of: items.map(\.id), initial: true) { _, ids in
            if selected == nil || !ids.contains(selected!) { selected = ids.first }
        }
        .onChange(of: photoItems) { _, chosen in
            let targetRegistration = reg
            Task { @MainActor in
                importing = true
                defer { importing = false; photoItems = [] }
                for item in chosen {
                    guard let data = try? await item.loadTransferable(type: Data.self), let image = AircraftPhotos.decodedPhoto(data) else {
                        problem = "One of the selected photos could not be read."; continue
                    }
                    if !photos.add(image, registration: targetRegistration) { problem = photos.errorMessage ?? "The photo could not be saved." }
                }
                selected = photos.galleries[targetRegistration]?.first?.id
            }
        }
        .alert("Aircraft photos", isPresented: Binding(get: { problem != nil }, set: { if !$0 { problem = nil } })) {
            Button("OK", role: .cancel) { problem = nil }
        } message: { Text(problem ?? "") }
    }
    private var controls: some View {
        HStack(spacing: 12) {
            PhotosPicker(selection: $photoItems, maxSelectionCount: max(1, AircraftPhotos.maximumPhotos - items.filter(\.userAdded).count), matching: .images) {
                Label(importing ? "Saving…" : "Add photos", systemImage: "photo.badge.plus")
            }.disabled(importing || reg.isEmpty || items.filter(\.userAdded).count >= AircraftPhotos.maximumPhotos)
            Spacer()
            if let current, items.first?.id != current.id {
                Button("Use as cover") {
                    if !photos.makeCover(current.id, registration: reg) { problem = photos.errorMessage ?? "The cover could not be saved." }
                }
            }
            Menu {
                Button("Retry public photo lookup") { Task { await photos.load(reg, retry: true) } }
            } label: { Image(systemName: "ellipsis.circle") }
        }.font(.caption).foregroundStyle(theme.accent)
    }
}

// MARK: - App shell

enum MainTab: Int, CaseIterable {
    case logbook, aircraft, totals, stats, calendar
    var title: String { ["Logbook", "Aircraft", "Totals", "Stats", "Calendar"][rawValue] }
    var icon: String { ["book", "airplane", "list.bullet", "chart.bar", "calendar"][rawValue] }
}

struct PrototypeTabIcon: Shape {
    let tab: MainTab
    func path(in rect: CGRect) -> Path {
        var p = Path()
        func point(_ x: CGFloat, _ y: CGFloat) -> CGPoint {
            CGPoint(x: rect.minX + x / 24 * rect.width, y: rect.minY + y / 24 * rect.height)
        }
        func line(_ points: [(CGFloat, CGFloat)], closed: Bool = false) {
            guard let first = points.first else { return }
            p.move(to: point(first.0, first.1))
            for item in points.dropFirst() { p.addLine(to: point(item.0, item.1)) }
            if closed { p.closeSubpath() }
        }
        switch tab {
        case .logbook:
            p.move(to: point(12, 5)); p.addQuadCurve(to: point(2, 3), control: point(6, 1))
            line([(2, 3), (2, 20)])
            p.addQuadCurve(to: point(12, 22), control: point(7, 18))
            p.addQuadCurve(to: point(22, 20), control: point(17, 18))
            p.addLine(to: point(22, 3)); p.addQuadCurve(to: point(12, 5), control: point(18, 1))
            line([(12, 5), (12, 22)])
        case .aircraft:
            // Top view, nose upward, as in the prototype.
            line([(12, 1), (12, 23)])
            line([(9.5, 4), (12, 1), (14.5, 4)])
            line([(12, 8), (3, 11), (3, 14), (12, 11), (21, 14), (21, 11)], closed: true)
            line([(12, 18.5), (7, 23), (17, 23)], closed: true)
        case .totals:
            for y in [CGFloat(5), 12, 19] {
                p.addEllipse(in: CGRect(x: point(2, y - 1.4).x, y: point(2, y - 1.4).y,
                                       width: rect.width * 2.8 / 24, height: rect.height * 2.8 / 24))
                line([(9, y), (22, y)])
            }
        case .stats:
            line([(2, 2), (2, 22), (23, 22)])
            line([(7, 18), (7, 14)]); line([(13, 18), (13, 8)])
            line([(19, 18), (19, 3)])
        case .calendar:
            p.addRoundedRect(in: CGRect(x: point(2, 5).x, y: point(2, 5).y,
                width: rect.width * 20 / 24, height: rect.height * 17 / 24), cornerSize: CGSize(width: 3, height: 3))
            line([(2, 10), (22, 10)]); line([(7, 2), (7, 7)]); line([(17, 2), (17, 7)])
            for y in [CGFloat(14), 18] { for x in [CGFloat(7), 12, 17] {
                p.addEllipse(in: CGRect(x: point(x - 0.6, y - 0.6).x, y: point(x - 0.6, y - 0.6).y,
                    width: rect.width * 1.2 / 24, height: rect.height * 1.2 / 24))
            } }
        }
        return p
    }
}

struct ContentView: View {
    @StateObject private var store = FlightStore()
    @StateObject private var theme = AppTheme()
    @StateObject private var photos = AircraftPhotos()
    @StateObject private var airports = AirportCatalog()
    @State private var tab: MainTab = .logbook
    @State private var more = false
    @State private var adding = false
    var body: some View {
        VStack(spacing: 0) {
            header
            Group {
                if more { MoreScreen(onImportFinished: { more = false; tab = .logbook }) }
                else {
                    switch tab {
                    case .logbook: LogbookScreen()
                    case .aircraft: AircraftScreen()
                    case .totals: TotalsScreen()
                    case .stats: StatsScreen()
                    case .calendar: CalendarScreen()
                    }
                }
            }.frame(maxWidth: .infinity, maxHeight: .infinity)
            tabBar
        }.background(theme.background.ignoresSafeArea()).foregroundStyle(theme.text)
            .environmentObject(store).environmentObject(theme).environmentObject(photos).environmentObject(airports)
            .preferredColorScheme(theme.dark ? .dark : .light).tint(theme.accent)
            .sheet(isPresented: $adding) {
                FlightEditor()
                    .environmentObject(store)
                    .environmentObject(theme)
                    .environmentObject(photos)
                    .environmentObject(airports)
            }
            .alert(AppBrand.name, isPresented: Binding(get: { store.errorMessage != nil }, set: { if !$0 { store.errorMessage = nil } })) {
                Button("OK", role: .cancel) { store.errorMessage = nil }
            } message: { Text(store.errorMessage ?? "") }
    }
    private var header: some View {
        HStack {
            Button { more.toggle() } label: {
                Image(systemName: more ? "xmark" : "line.3.horizontal")
                    .font(.system(size: 21, weight: .semibold)).frame(width: 44, height: 44)
                    .background(theme.surface).clipShape(Circle())
                    .overlay(Circle().stroke(theme.line, lineWidth: 1))
            }.accessibilityLabel(more ? "Close More" : "Open More")
            Spacer()
            Text(more ? "More" : tab.title).font(.system(size: 25, weight: .heavy, design: .rounded))
            Spacer()
            Button { adding = true } label: {
                Image(systemName: "plus").font(.system(size: 29, weight: .regular))
                    .foregroundStyle(Color(hex: 0x15202A)).frame(width: 46, height: 46)
                    .background(theme.accent).clipShape(Circle())
            }.accessibilityLabel("Add flight")
        }.buttonStyle(.plain).padding(.horizontal, 18).padding(.vertical, 16)
            .background(theme.background).overlay(alignment: .bottom) { Rectangle().fill(theme.line).frame(height: 1) }
    }
    private var tabBar: some View {
        HStack(spacing: 3) {
            ForEach(MainTab.allCases, id: \.rawValue) { item in
                Button { more = false; tab = item } label: {
                    VStack(spacing: 7) {
                        PrototypeTabIcon(tab: item).stroke(style: StrokeStyle(lineWidth: 1.8, lineCap: .round, lineJoin: .round))
                            .frame(width: 25, height: 25).accessibilityHidden(true)
                        Text(item.title).font(.system(size: 11, weight: .medium))
                    }.frame(maxWidth: .infinity).padding(.vertical, 12)
                        .foregroundStyle(!more && tab == item ? theme.accent : theme.muted)
                        .background(!more && tab == item ? theme.accent.opacity(0.13) : Color.clear)
                        .clipShape(RoundedRectangle(cornerRadius: 21))
                }
            }
        }.buttonStyle(.plain).padding(.horizontal, 8).padding(.top, 8).padding(.bottom, 2)
            .background(theme.surface.ignoresSafeArea(edges: .bottom))
            .overlay(alignment: .top) { Rectangle().fill(theme.line).frame(height: 1) }
    }
}

struct SessionPhoto: View {
